INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1,'ivorycoast','Zino Cigares & Lounge — Flagship Zone 4','Abidjan, Marcory — Rue Paul Langevin','Flagship Lounge & Cave','+225 27 22 51 05 09','€€€€','Inauguré le 6 janv. 2025 par les frères Kamal et Charan Daswani. 160 m², cave humidifiée où l\'on entre 120 m² (450+ refs Habanos), fumoir lounge 120 m² (150 personnes). Ouvert 10h-2h. Groupe présent depuis 1980, inauguré par Zino Davidoff en personne.','cigars-connect.com',1,'2026-03-18 09:43:40','2026-10-29 12:49:17','10h–2h',NULL,NULL,NULL,NULL,0,'Opened on 6 January 2025 by the brothers Kamal and Charan Daswani. One hundred and sixty square metres: a 120 m² walk-in humidor holding over 450 Habanos references, and a 120 m² smoking lounge seating 150. Open 10am to 2am. The group has been present since 1980, opened by Zino Davidoff himself.','Inaugurada el 6 de enero de 2025 por los hermanos Kamal y Charan Daswani. Ciento sesenta metros cuadrados: humidor walk-in de 120 m² con más de 450 referencias de habanos, y salón de fumadores de 120 m² para 150 personas. Abierto de 10:00 a 2:00. El grupo está presente desde 1980; lo inauguró el propio Zino Davidoff.','Am 6. Januar 2025 von den Brüdern Kamal und Charan Daswani eröffnet. 160 m²: ein begehbarer Humidor von 120 m² mit über 450 Habanos-Referenzen und eine Raucherlounge von 120 m² für 150 Personen. Geöffnet von 10 bis 2 Uhr. Die Gruppe besteht seit 1980; eröffnet wurde sie von Zino Davidoff persönlich.','2025 年 1 月 6 日由卡迈勒与查兰·达斯瓦尼兄弟开设。总面积一百六十平方米：一百二十平方米的步入式恒湿雪茄柜，陈列逾四百五十款 Habanos；另设一百二十平方米、可容纳一百五十人的雪茄休息厅。营业时间 10:00 至次日 02:00。集团自 1980 年经营至今，由 Zino Davidoff 亲自揭幕。','افتُتح في السادس من كانون الثاني/يناير 2025 على يد الأخوين كمال وتشاران داسواني. مئة وستون مترًا مربعًا: مستودع ترطيب يمكن دخوله بمساحة 120 م² يضمّ ما يزيد على 450 صنفًا من سيجار هابانوس، وصالة تدخين بمساحة 120 م² تتّسع لمئة وخمسين شخصًا. يفتح من العاشرة صباحًا حتى الثانية فجرًا. المجموعة قائمة منذ 1980، وقد افتتحه زينو دافيدوف بنفسه.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2,'ivorycoast','Zino Cigares — Cap Sud','Abidjan, Rue des Jardins — Galerie Cap Sud','Civette & Cave à Cigares','+225 27 22 51 05 10','€€€€','Inaugurée en déc. 2020. Toutes marques Habanos, Arturo Fuente, Davidoff, Rocky Patel, La Flor Dominicana, Plasencia, Gurkha. Accessoires Elie Bleu, Chacom, Zippo.','baab.ci',1,'2026-03-18 09:43:40','2026-10-21 17:19:55',NULL,NULL,NULL,NULL,NULL,0,'Opened in December 2020. The full range of Habanos brands, alongside Arturo Fuente, Davidoff, Rocky Patel, La Flor Dominicana, Plasencia and Gurkha. Accessories by Elie Bleu, Chacom and Zippo.','Inaugurada en diciembre de 2020. Toda la gama de marcas Habanos, junto a Arturo Fuente, Davidoff, Rocky Patel, La Flor Dominicana, Plasencia y Gurkha. Accesorios de Elie Bleu, Chacom y Zippo.','Im Dezember 2020 eröffnet. Das gesamte Habanos-Sortiment sowie Arturo Fuente, Davidoff, Rocky Patel, La Flor Dominicana, Plasencia und Gurkha. Accessoires von Elie Bleu, Chacom und Zippo.','2020 年 12 月开业。Habanos 全系列品牌，以及 Arturo Fuente、Davidoff、Rocky Patel、La Flor Dominicana、Plasencia、Gurkha。配件：Elie Bleu、Chacom、Zippo。','افتُتحت في ديسمبر 2020. جميع ماركات هابانوس، وArturo Fuente، وDavidoff، وRocky Patel، وLa Flor Dominicana، وPlasencia، وGurkha. إكسسوارات Elie Bleu وChacom وZippo.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (3,'ivorycoast','Zino Bar Lounge','Abidjan, Marcory Résidentiel — Bvd de la Lorraine, Rue des Citronniers','Bar & Lounge Cigares','+225 07 07 56 43 43','€€€','Lounge cigares d\'Abidjan, à Marcory Résidentiel. Sélection de Habanos et de cigares premium.','TripAdvisor, avis vérifiés',1,'2026-03-18 09:43:40','2026-10-21 17:16:22',NULL,NULL,NULL,NULL,NULL,0,'Cigar lounge in Abidjan, in Marcory Résidentiel. A selection of Habanos and premium cigars.','Cigar lounge en Abiyán, en Marcory Résidentiel. Selección de Habanos y puros premium.','Zigarrenlounge in Abidjan, im Viertel Marcory Résidentiel. Auswahl an Habanos und Premium-Zigarren.','阿比让 Marcory Résidentiel 区的雪茄厅。精选 Habanos 与高端雪茄。','صالة سيجار في أبيدجان، بحي ماركوري السكني. تشكيلة من هابانوس والسيجار الفاخر.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (4,'ivorycoast','Cigarro CI — Diamond Center Beverly Hills','Abidjan, Beverly Hills — Diamond Center','Lounge Cigares & Civette','+225 07 69 03 00 30','€€€','Lounge Cigarro CI dans le Diamond Center Beverly Hills. Instagram: @cigarro.ci','fourni par l\'établissement — relu le 17 septembre 2026 : son compte Instagram, porté sur la fiche, donne les deux adresses, Diamond Center à Beverly Hills et rue du Docteur Blanchard en Zone 4 ; aucun site ni presse',1,'2026-03-18 09:43:40','2026-09-18 07:10:28',NULL,NULL,NULL,'@cigarro.ci',5.0,1,'Cigarro CI lounge in the Diamond Center Beverly Hills. Instagram: @cigarro.ci','Lounge Cigarro CI en el Diamond Center Beverly Hills. Instagram: @cigarro.ci','Cigarro-CI-Lounge im Diamond Center Beverly Hills. Instagram: @cigarro.ci','位于 Diamond Center Beverly Hills 的 Cigarro CI 雪茄厅。Instagram：@cigarro.ci','صالة «سيغارو CI» في مركز دياموند بيفرلي هيلز. إنستغرام: @cigarro.ci',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (5,'ivorycoast','Cigarro CI — Rue du Dr Blanchard Zone 4','Abidjan, Zone 4 — Rue du Docteur Blanchard','Lounge Cigares & Civette','+225 07 69 03 00 30','€€€','Deuxième adresse Cigarro CI en Zone 4. Instagram: @cigarro.ci','fourni par l\'établissement — relu le 17 septembre 2026 : son compte Instagram, porté sur la fiche, donne les deux adresses, Diamond Center à Beverly Hills et rue du Docteur Blanchard en Zone 4 ; aucun site ni presse',1,'2026-03-18 09:43:40','2026-09-18 07:10:28',NULL,NULL,NULL,'@cigarro.ci',5.0,1,'Cigarro CI\'s second address, in Zone 4. Instagram: @cigarro.ci','La segunda dirección de Cigarro CI, en la Zona 4. Instagram: @cigarro.ci','Die zweite Adresse von Cigarro CI, in Zone 4. Instagram: @cigarro.ci','Cigarro CI 的第二家门店，位于 4 区。Instagram：@cigarro.ci','العنوان الثاني لـ«سيغارو CI» في المنطقة 4. إنستغرام: @cigarro.ci',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (6,'ivorycoast','Boca Chica Club Bar & Cigare Lounge','Abidjan, Plateau — Hôtel Noom (3e étage)','Hôtel Cigar Bar & Club',NULL,'€€€€','Lounge au 3e étage de l\'Hôtel Noom Plateau. Cigares de luxe, whiskys, champagnes, fauteuils Club cuir. Soul, Blues, Smooth Jazz.','baab.ci, bocachicaabidjan.com',1,'2026-03-18 09:43:40','2026-08-01 18:15:50',NULL,NULL,NULL,NULL,NULL,0,'Third-floor lounge at the Hôtel Noom Plateau. Luxury cigars, whiskies, champagnes and leather club armchairs. Soul, blues and smooth jazz.','Lounge en la tercera planta del Hôtel Noom Plateau. Puros de lujo, whiskies, champanes y sillones club de cuero. Soul, blues y smooth jazz.','Lounge im dritten Stock des Hôtel Noom Plateau. Luxuszigarren, Whiskys, Champagner und lederne Clubsessel. Soul, Blues und Smooth Jazz.','Hôtel Noom Plateau 三楼的休闲厅。奢华雪茄、威士忌、香槟与皮质俱乐部扶手椅。播放灵魂乐、蓝调与柔和爵士。','صالة في الطابق الثالث من فندق نووم بلاتو. سيجار فاخر وويسكي وشمبانيا وكراسي نادٍ جلدية. موسيقى سول وبلوز وجاز هادئ.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (7,'ivorycoast','Elite Cigar Abidjan','Abidjan','Restaurant, Lounge & Cigar Shop','+225 07 07 17 28 68','€€€','Repaire d\'amateurs, cadre discret et chaleureux. Restaurant, salon, boutique de cigares et terrasse.','baab.ci, Facebook',1,'2026-03-18 09:43:40','2026-08-26 11:06:16',NULL,NULL,NULL,NULL,NULL,0,'A haven for aficionados, discreet and warm. Restaurant, lounge, cigar shop and terrace.','Refugio de aficionados, de ambiente discreto y acogedor. Restaurante, salón, tienda de puros y terraza.','Ein Treffpunkt für Liebhaber, diskret und behaglich. Restaurant, Lounge, Zigarrenladen und Terrasse.','雪茄爱好者聚集地，环境低调温馨。设餐厅、休息室、雪茄专卖店与露台。','ملتقى عشاق السيجار، بأجواء هادئة ودافئة. مطعم، وصالة، ومتجر سيجار، وشرفة.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (8,'ivorycoast','Iroko Cigar Lounge Bar','Abidjan','Lounge Cigares & Bar',NULL,'€€€','Lounge cigares à Abidjan. Instagram: @irokoloungeabidjan','baab.ci',1,'2026-03-18 09:43:40','2026-09-02 15:29:10',NULL,NULL,NULL,'irokoloungeabidjan',NULL,0,'Cigar lounge in Abidjan. Instagram: @irokoloungeabidjan','Cigar lounge en Abiyán. Instagram: @irokoloungeabidjan','Zigarrenlounge in Abidjan. Instagram: @irokoloungeabidjan','阿比让的雪茄休闲厅。Instagram：@irokoloungeabidjan','صالة سيجار في أبيدجان. إنستغرام: @irokoloungeabidjan',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (9,'ivorycoast','Cohiba\'r Club','Abidjan, Deux-Plateaux Vallon — Galerie Sainte Cécile, Rue des Jardins','Civette Cigares',NULL,'€€€','Fondée en 2018. Vente cigares nicaraguayens, dominicains et cubains, accessoires.','goafricaonline.com',1,'2026-03-18 09:43:40','2026-08-01 18:08:35',NULL,NULL,NULL,NULL,NULL,0,'Founded in 2018. Sells Nicaraguan, Dominican and Cuban cigars, plus accessories.','Fundado en 2018. Venta de puros nicaragüenses, dominicanos y cubanos, y accesorios.','2018 gegründet. Verkauf nicaraguanischer, dominikanischer und kubanischer Zigarren sowie Zubehör.','创立于 2018 年。经营尼加拉瓜、多米尼加与古巴雪茄及配件。','تأسّس عام 2018. يبيع السيجار النيكاراغوي والدومينيكي والكوبي، إضافة إلى الملحقات.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (10,'ivorycoast','COHIBA\'R — Riviera Palmeraie','Abidjan, près pharmacie Divine Onction, Deux-Plateaux SOCOCE Cocody','Civette Cigares',NULL,'€€€','Magasin cigares depuis 2009 à la Riviera Palmeraie. Cigares cubains, nicaraguayens, dominicains.','goafricaonline.com',1,'2026-03-18 09:43:40','2026-10-29 12:49:17',NULL,NULL,NULL,NULL,NULL,0,'Cigar shop in Riviera Palmeraie since 2009. Cuban, Nicaraguan and Dominican cigars.','Tienda de puros en Riviera Palmeraie desde 2009. Puros cubanos, nicaragüenses y dominicanos.','Zigarrenladen in Riviera Palmeraie seit 2009. Kubanische, nicaraguanische und dominikanische Zigarren.','自 2009 年营业于 Riviera Palmeraie 的雪茄行。经营古巴、尼加拉瓜与多米尼加雪茄。','متجر سيجار في ريفييرا بالميري منذ 2009. سيجار كوبي ونيكاراغوي ودومينيكي.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (11,'ivorycoast','Fagot Cigare','Abidjan, Riviéra Palmeraie — après la cité universitaire de la Riviéra 2','Manufacture Artisanale Ivoirienne','+225 07 04 05 70 70','€€','Atelier de cigares annoncé à Abidjan, dans le quartier de la Riviéra Palmeraie ; aucune source publique ne confirme son activité aujourd\'hui.','à vérifier — relu le 28 octobre 2026 : le site officiel de la maison n\'existe plus ; aucune page, aucun compte ni article de presse ne confirme l\'activité actuelle de l\'atelier (cinq requêtes en français et en anglais)',1,'2026-03-18 09:43:40','2026-10-29 07:54:40',NULL,NULL,NULL,'fagot_cigare',NULL,0,'A cigar workshop listed in the Riviéra Palmeraie district of Abidjan; no public source confirms that it is active today.','Taller de puros indicado en el barrio de Riviéra Palmeraie de Abiyán; ninguna fuente pública confirma que siga activo hoy.','Im Viertel Riviéra Palmeraie von Abidjan angekündigte Zigarrenwerkstatt; keine öffentliche Quelle bestätigt ihre heutige Tätigkeit.','该处标注在阿比让 Riviera Palmeraie 区设有雪茄作坊，但没有公开来源证实其目前仍在营业。','ورشة سيجار يُشار إليها في حي ريفييرا بالميري بمدينة أبيدجان، لكن لا يؤكد أي مصدر عام أنها ما زالت تعمل اليوم.',NULL,NULL,NULL);
