INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (23,'ethiopia','Sheraton Addis — Cigar Bar','Addis-Abeba, Sheraton Addis Hotel','Hôtel Cigar Bar','+251 11 517 1717','€€€€','Lounge cigares premium au Sheraton Addis d\'Addis-Abeba. Habanos sélectionnés, spiritueux fins, atmosphère raffinée.','sheraton.com',1,'2026-03-18 09:43:40','2026-10-21 17:19:55',NULL,NULL,NULL,NULL,NULL,0,'Premium cigar lounge at Sheraton Addis, Addis-Abeba. Curated Habanos selection, fine spirits, refined atmosphere.','Cigar lounge premium en el Sheraton Addis de Adís Abeba. Habanos seleccionados, destilados finos y ambiente refinado.','Premium-Zigarrenlounge im Sheraton Addis in Addis Abeba. Ausgewählte Habanos, edle Spirituosen, raffinierte Atmosphäre.','阿迪斯阿贝巴 Sheraton Addis 酒店的高端雪茄厅。精选 Habanos、优质烈酒，氛围考究。','صالة سيجار فاخرة في فندق شيراتون أديس بأديس أبابا. سيجار هابانوس منتقى ومشروبات روحية راقية وأجواء أنيقة.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (24,'tanzania','Zanzibar Cigar Club — Stone Town','Stone Town, Zanzibar','Lounge & Cave',NULL,'€€€','Lounge cigares dans la vieille ville de Zanzibar classée UNESCO. Ambiance spice island.','tripadvisor.com avis vérifiés',1,'2026-03-18 09:43:40','2026-10-21 17:19:55',NULL,NULL,NULL,NULL,NULL,0,'Cigar lounge in the UNESCO-listed old town of Zanzibar. Spice island atmosphere.','Cigar lounge en el casco antiguo de Zanzíbar, Patrimonio de la Humanidad. Ambiente de isla de las especias.','Zigarrenlounge in der UNESCO-gelisteten Altstadt von Sansibar. Gewürzinsel-Atmosphäre.','位于桑给巴尔被联合国教科文组织列入名录的古城内的雪茄厅。香料岛风情。','صالة سيجار في المدينة القديمة بزنجبار، المدرجة على قائمة اليونسكو. أجواء جزيرة التوابل.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (25,'france','À La Civette (fondée 1716)','Paris 1er — 157 Rue Saint-Honoré, près Palais-Royal','Civette Historique (plus ancienne du monde)','+33 1 42 96 04 99','€€€€','Fondée en 1716 et en activité sans interruption depuis. Clients historiques : Danton, Napoléon, Robespierre, Mirabeau, Degas, George Sand. Plus de 350 références de Cuba, du Honduras, du Nicaragua et de République dominicaine. Pipes et spiritueux.','alacivette.com officiel',1,'2026-03-18 09:43:40','2026-10-29 12:49:17',NULL,NULL,NULL,NULL,NULL,0,'Founded in 1716 and trading without interruption ever since. Historic patrons: Danton, Napoleon, Robespierre, Mirabeau, Degas, George Sand. Over 350 references from Cuba, Honduras, Nicaragua and the Dominican Republic. Pipes and spirits.','Fundada en 1716 y en activo sin interrupción desde entonces. Clientes históricos: Danton, Napoleón, Robespierre, Mirabeau, Degas, George Sand. Más de 350 referencias de Cuba, Honduras, Nicaragua y República Dominicana. Pipas y destilados.','1716 gegründet und seither ohne Unterbrechung in Betrieb. Historische Kunden: Danton, Napoleon, Robespierre, Mirabeau, Degas, George Sand. Über 350 Referenzen aus Kuba, Honduras, Nicaragua und der Dominikanischen Republik. Pfeifen und edle Spirituosen.','1716 年创立，此后经营从未中断。历史上的顾客包括丹东、拿破仑、罗伯斯庇尔、米拉波、德加与乔治·桑。备有 350 余款来自古巴、洪都拉斯、尼加拉瓜和多米尼加共和国的产品，另售烟斗与精致烈酒。','تأسّست عام 1716 وظلّت تعمل دون انقطاع منذ ذلك الحين. من زبائنها التاريخيين: دانتون ونابليون وروبسبير وميرابو وديغا وجورج ساند. ما يزيد على 350 صنفًا من كوبا وهندوراس ونيكاراغوا وجمهورية الدومينيكان، إضافة إلى الغلايين والمشروبات الروحية.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (26,'france','Bar Aristide (Hôtel Lutetia)','Paris 6e — 45 Boulevard Raspail','Palace Cigar Bar','+33 1 49 54 46 46','€€€€','Premier palace Art Nouveau de Paris. Bar Aristide avec deux fumoirs distincts. Sélection pointue de cigares cubains, mixologie signature raffinée. Matisse, Saint-Exupéry y fumèrent.','cigaroa.com, hotel-lutetia.com',1,'2026-03-18 09:43:40','2026-10-29 12:49:17',NULL,NULL,NULL,NULL,NULL,0,'Paris\'s first Art Nouveau palace hotel. The Aristide bar with two separate smoking rooms. A sharp selection of Cuban cigars and refined signature mixology. Matisse and Saint-Exupéry smoked here.','El primer palacio modernista de París. El bar Aristide, con dos salones de fumadores independientes. Selección exigente de puros cubanos y coctelería de autor refinada. Matisse y Saint-Exupéry fumaron aquí.','Das erste Jugendstil-Grandhotel von Paris. Die Aristide-Bar mit zwei getrennten Rauchsalons. Anspruchsvolle kubanische Zigarrenauswahl und raffinierte Signature-Mixologie. Matisse und Saint-Exupéry rauchten hier.','巴黎首家新艺术风格宫殿酒店。Aristide 酒吧设两间独立吸烟室。古巴雪茄选品讲究，招牌调酒精致。马蒂斯与圣埃克苏佩里曾在此吸烟。','أول فندق قصر بطراز الآرت نوفو في باريس. بار «أريستيد» بصالتَي تدخين منفصلتين. تشكيلة دقيقة من السيجار الكوبي وفنّ كوكتيل مميّز. دخّن هنا ماتيس وسانت إكزوبيري.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (27,'france','Le Gaspard (La Réserve Paris)','Paris 8e — 42 avenue Gabriel','Palace Cigar Room','+33 1 58 36 60 60','€€€€','Cigar room dans l\'hôtel La Réserve Paris, avenue Gabriel.','enthusiastreport.com, la-reserve.com',1,'2026-03-18 09:43:40','2026-08-05 11:35:28',NULL,NULL,NULL,NULL,NULL,0,'Cigar room in the hotel La Réserve Paris, avenue Gabriel.','Cigar room en el hotel La Réserve Paris, avenue Gabriel.','Cigar Room im Hotel La Réserve Paris, Avenue Gabriel.','位于巴黎 La Réserve 酒店（加布里埃尔大道）的雪茄室。','غرفة سيجار في فندق لا ريزيرف باريس، بجادة غابرييل.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (28,'france','L\'Héritage 105 — Cigar Bar','Paris 8e — 105 Rue du Faubourg Saint-Honoré','Restaurant, Lounge & Cigar Bar','+33 1 42 89 47 15','€€€€','Concept trois-en-un: restaurant bistronomique, lounge bar, cigar bar. Sélection de havanes d\'exception, spiritueux choisis. Au coeur du Paris luxueux.','lheritage105.com officiel',1,'2026-03-18 09:43:40','2026-08-01 18:08:34',NULL,NULL,NULL,NULL,NULL,0,'A three-in-one concept: bistronomy restaurant, lounge bar and cigar bar. Exceptional Havanas and a curated spirits list, in the heart of luxury Paris.','Concepto tres en uno: restaurante bistronómico, lounge bar y cigar bar. Selección de habanos excepcionales y destilados escogidos, en pleno París del lujo.','Drei-in-eins-Konzept: Bistronomie-Restaurant, Lounge-Bar und Zigarrenbar. Außergewöhnliche Havannas und ausgewählte Spirituosen, im Herzen des luxuriösen Paris.','三合一概念：小酒馆式美食餐厅、休闲酒吧与雪茄吧。臻选哈瓦那雪茄与精选烈酒，坐落于巴黎奢华腹地。','مفهوم ثلاثي: مطعم بيسترونومي وصالة بار وبار سيجار. تشكيلة استثنائية من سيجار هافانا ومشروبات روحية منتقاة، في قلب باريس الفاخرة.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (29,'france','Peninsula Lounge Kléber','Paris 16e — 19 Avenue Kléber (Hôtel Peninsula)','Palace Cigar Lounge','+33 1 58 12 28 88','€€€€','Lounge Kléber dans l\'hôtel Peninsula Paris, avenue Kléber.','cigaroa.com',1,'2026-03-18 09:43:40','2026-10-21 17:16:22',NULL,NULL,NULL,NULL,NULL,0,'The Kléber lounge in the Peninsula Paris hotel, avenue Kléber.','El lounge Kléber del hotel Peninsula Paris, avenue Kléber.','Die Kléber-Lounge im Hotel Peninsula Paris, Avenue Kléber.','Peninsula Paris 酒店（Kléber 大道）的 Kléber 休息厅。','صالة كليبر في فندق بينينسولا باريس، بجادة كليبر.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (30,'spain','La Casa del Habano — Madrid','Madrid — Paseo de Recoletos 1','La Casa del Habano Officielle',NULL,'€€€€','Adresse répertoriée paseo de Recoletos 1, à Madrid. Le plan des franchises de La Casa del Habano compte une Casa à Madrid ; l\'annuaire habanos.com n\'en classe aucune en Espagne, et cette adresse n\'est confirmée par aucun des deux.','à vérifier — relu le 18 septembre 2026 : le plan des franchises lacasadelhabano.com (état du 30 août 2026, lu le 18 septembre 2026) compte une Casa à Madrid ; l\'annuaire habanos.com (4 437 lieux, lu le 17 septembre 2026) n\'en classe aucune en Espagne ; l\'adresse de la fiche, paseo de Recoletos 1, et le nom Club Pasión Habanos qu\'elle portait (club madrilène, calle Ferraz 2) ne sont confirmés par aucun des deux',1,'2026-03-18 09:43:40','2026-10-21 17:19:55',NULL,NULL,NULL,NULL,NULL,0,'An address listed at Paseo de Recoletos 1, Madrid. The La Casa del Habano franchise map counts one Casa in Madrid; the habanos.com directory classes none in Spain, and this address is confirmed by neither.','Dirección registrada en el paseo de Recoletos 1, Madrid. El mapa de franquicias de La Casa del Habano cuenta una Casa en Madrid; el directorio de habanos.com no clasifica ninguna en España, y esta dirección no la confirma ninguno de los dos.','Eine unter Paseo de Recoletos 1, Madrid, verzeichnete Adresse. Die Franchise-Karte von La Casa del Habano zählt eine Casa in Madrid; das Verzeichnis von habanos.com führt keine in Spanien, und diese Adresse bestätigt keines von beiden.','登记于马德里雷科莱托斯大道1号的一处地址。La Casa del Habano 的特许经营地图在马德里计有一家 Casa；habanos.com 的名录在西班牙未归类任何一家，而这一地址两者都未确认。','عنوان مسجَّل في باسيو دي ريكوليتوس 1 بمدريد. تعدّ خريطة امتيازات La Casa del Habano فرعًا واحدًا في مدريد؛ ولا يصنّف دليل habanos.com أيَّ فرع في إسبانيا، ولا يؤكّد هذا العنوان أيٌّ منهما.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (31,'spain','Gimeno — La Rambla','Barcelona — Ramblas 100, Barrio Gótico','Civette Historique (fondée 1920)','+34 93 318 49 47','€€€€','Fondée en 1920, référence absolue du cigare à Barcelone. Rez-de-chaussée + sous-sol cave humidifiée où l\'on entre. Toute la gamme Altadis/Habanos + accessoires. 10h-19h lun-sam.','barcelona.com, tripadvisor vérifiés',1,'2026-03-18 09:43:40','2026-08-25 02:40:14',NULL,NULL,NULL,NULL,NULL,0,'Founded in 1920, the absolute cigar reference in Barcelona. Ground floor plus a basement walk-in humidor. The full Altadis/Habanos range and accessories. Open 10am–7pm, Monday to Saturday.','Fundado en 1920, la referencia absoluta del puro en Barcelona. Planta baja y humidor walk-in en el sótano. Toda la gama Altadis/Habanos y accesorios. De 10:00 a 19:00, de lunes a sábado.','1920 gegründet, die absolute Zigarrenreferenz in Barcelona. Erdgeschoss plus begehbarer Humidor im Untergeschoss. Das komplette Altadis/Habanos-Sortiment und Zubehör. Mo–Sa 10–19 Uhr.','创立于 1920 年，巴塞罗那雪茄的绝对标杆。一楼加地下层步入式雪茄柜。Altadis／Habanos 全系列与配件。周一至周六 10:00–19:00。','تأسّس عام 1920، وهو المرجع المطلق للسيجار في برشلونة. طابق أرضي وقبو بمرطّبة قابلة للدخول. تشكيلة ألتاديس/هابانوس الكاملة والملحقات. من 10:00 إلى 19:00، الاثنين إلى السبت.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (32,'spain','Bluesman Cigar Lounge — Hotel El Palace','Barcelona — Gran Via de les Corts Catalanes 668 (El Palace Hotel)','Palace Cigar Lounge','+34 93 510 11 30','€€€€','Lounge cigares dans l\'hôtel El Palace de Barcelone, Gran Via de les Corts Catalanes.','hotelpalacebarcelona.com officiel',1,'2026-03-18 09:43:40','2026-08-05 12:02:56',NULL,NULL,NULL,NULL,NULL,0,'Cigar lounge in the El Palace hotel in Barcelona, Gran Via de les Corts Catalanes.','Cigar lounge en el hotel El Palace de Barcelona, Gran Via de les Corts Catalanes.','Zigarrenlounge im Hotel El Palace in Barcelona, Gran Via de les Corts Catalanes.','位于巴塞罗那 El Palace 酒店（Gran Via de les Corts Catalanes）的雪茄厅。','صالة سيجار في فندق إل بالاس ببرشلونة، بشارع غران فيا دي ليس كورتس كاتالانس.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (33,'spain','Cava Magallanes','Madrid — Rua de Magallanes 1','Cave & Lounge Premium','+34 91 446 69 96','€€€€','Davidoff Best Performance EMEA Award 2021. Cave de référence de Madrid, sélection premium, accords cigare-spiritueux.','cigarjournal.com Golden Band Awards 2021',1,'2026-03-18 09:43:40','2026-10-21 17:19:55',NULL,NULL,NULL,NULL,NULL,0,'Davidoff Best Performance EMEA Award 2021. Madrid\'s benchmark shop, premium selection, cigar-and-spirits pairings.','Davidoff Best Performance EMEA Award 2021. El estanco de referencia de Madrid, selección premium y maridajes puro-destilado.','Davidoff Best Performance EMEA Award 2021. Madrids maßgeblicher Laden, Premium-Auswahl, Zigarren-Spirituosen-Pairings.','获 2021 年 Davidoff Best Performance EMEA Award。马德里的标杆商行，高端精选，雪茄与烈酒搭配。','جائزة دافيدوف «Best Performance EMEA» لعام 2021. المتجر المرجعي في مدريد، بتشكيلة فاخرة ومزاوجات بين السيجار والمشروبات الروحية.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (34,'germany','Cigarworld Lounge','Düsseldorf — Burghofstrasse 28, 40223','Cave & Lounge Géant (fondé 2005)','+49 211 1593 985','€€€€','Le plus grand lounge cigares d\'Allemagne, fondé en 2005. Plus de 3 000 références, cave humidifiée où l\'on entre professionnel, salons de dégustation climatisés à Düsseldorf.','cigarworld.de, londoncigarsmoker.com',1,'2026-03-18 09:43:40','2026-10-29 07:39:05',NULL,NULL,NULL,NULL,NULL,0,'Germany\'s largest cigar lounge, founded in 2005. Over 3,000 references, professional walk-in humidor, air-conditioned tasting rooms in Düsseldorf.','El mayor cigar lounge de Alemania, fundado en 2005. Más de 3000 referencias, humidor walk-in profesional y salas de degustación climatizadas en Düsseldorf.','Deutschlands größte Zigarrenlounge, gegründet 2005. Über 3000 Referenzen, professioneller begehbarer Humidor, klimatisierte Verkostungsräume in Düsseldorf.','德国规模庞大的雪茄厅，创立于 2005 年。逾 3000 款雪茄、专业步入式雪茄柜，以及杜塞尔多夫的恒温品鉴室。','أكبر صالة سيجار في ألمانيا، تأسّست عام 2005. ما يزيد على 3000 صنف، ومستودع ترطيب احترافي يمكن دخوله، وقاعات تذوّق مكيّفة في دوسلدورف.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (35,'germany','La Casa del Habano Hamburg — Chilehaus','Hamburg — Burchardstrasse 15, Chilehaus C, 20095','La Casa del Habano Officielle','+49 40 30704880','€€€€','Dans le Chilehaus, bâtiment expressionniste de 1924 classé Patrimoine Mondial UNESCO. LCDH de Hambourg depuis 2006. Géré par Janet et Christoph Walters, experts cigares 3e génération. Lounge intérieur, rums, cognacs, champagnes.','flavoredtimes.com, cigarjournal.com',1,'2026-03-18 09:43:40','2026-10-21 17:19:55',NULL,NULL,NULL,NULL,NULL,0,'In the Chilehaus, a 1924 Expressionist building listed as UNESCO World Heritage. Hamburg\'s La Casa del Habano since 2006. Run by Janet and Christoph Walters, third-generation cigar experts. Indoor lounge, rums, cognacs, champagnes.','En el Chilehaus, edificio expresionista de 1924 declarado Patrimonio Mundial de la UNESCO. La Casa del Habano de Hamburgo desde 2006. Dirigida por Janet y Christoph Walters, expertos cigarreros de tercera generación. Lounge interior, rones, coñacs y champanes.','Im Chilehaus, einem expressionistischen Bau von 1924 und UNESCO-Welterbe. Hamburgs La Casa del Habano seit 2006. Geführt von Janet und Christoph Walters, Zigarrenexperten in dritter Generation. Innenlounge, Rum, Cognac, Champagner.','位于 Chilehaus 内，这是一栋 1924 年的表现主义建筑，列入联合国教科文组织世界遗产。汉堡 La Casa del Habano，自 2006 年起营业。由 Janet 与 Christoph Walters 经营，二人为第三代雪茄专家。室内休息厅，朗姆酒、干邑、香槟。','في مبنى تشيلهاوس، وهو مبنى تعبيري من عام 1924 مدرج على قائمة التراث العالمي لليونسكو. «لا كاسا ديل هابانو» في هامبورغ منذ 2006. تديره Janet وChristoph Walters، خبيرا سيجار من الجيل الثالث. صالة داخلية، وروم، وكونياك، وشمبانيا.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (36,'germany','Duske & Duske','Hamburg — Große Bleichen 36','Cave & Habanos Specialist','+49 40 343385','€€€','Façade historique de marchand de Porto, spécialiste Habanos officiel. Cigares cubains complets. Accords avec Prime\'s Rum (mélange caribéen) et plus de 150 types de Porto et Madeira vintage (dont 1870). Futur membre réseau LCDH.','flavoredtimes.com',1,'2026-03-18 09:43:40','2026-10-21 17:16:22',NULL,NULL,NULL,NULL,NULL,0,'A historic port-wine merchant\'s shopfront, and an official Habanos specialist. The full range of Cuban cigars. Pairings with Prime\'s Rum (a Caribbean blend) and more than 150 vintage ports and madeiras, one of them from 1870. A future member of the La Casa del Habano network.','Antigua fachada de comerciante de oporto, y especialista oficial de Habanos. Toda la gama de puros cubanos. Maridajes con Prime\'s Rum (mezcla caribeña) y más de 150 oportos y madeiras añejos, uno de ellos de 1870. Futuro miembro de la red La Casa del Habano.','Historische Fassade eines Portweinhändlers und offizieller Habanos-Spezialist. Das vollständige Sortiment kubanischer Zigarren. Pairings mit Prime\'s Rum (karibischer Blend) und über 150 gereiften Portweinen und Madeiras, darunter ein 1870er. Künftiges Mitglied des La-Casa-del-Habano-Netzes.','门面沿用旧时波特酒商行的样式，为 Habanos 官方专门店。古巴雪茄品类齐全。可搭配 Prime\'s Rum（加勒比调和朗姆），以及逾一百五十款陈年波特与马德拉，其中一款为 1870 年份。将加入 La Casa del Habano 网络。','واجهة تاريخية لتاجر نبيذ بورتو، ومتجر متخصّص معتمد من هابانوس. تشكيلة كاملة من السيجار الكوبي. مزاوجات مع Prime\'s Rum (مزيج كاريبي) وأكثر من مئة وخمسين صنفًا من نبيذ بورتو والماديرا المعتّق، أحدها من عام 1870. عضو مرتقب في شبكة لا كاسا ديل هابانو.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (37,'germany','Carlos André Cigar Lounge (Se7en Oceans)','Hamburg — Europa Passage, 2e étage, Ballindamm 40','Restaurant Étoilé Cigar Lounge','+49 40 32507944','€€€€','Lounge cigares dans le complexe gastronomique Se7en Oceans (restaurant étoilé Michelin). Cave humidifiée où l\'on entre. Vue sur le Binnenalster. La Aurora, Davidoff, cubains. Bar cocktail complet.','cigarjournal.com, flavoredtimes.com',1,'2026-03-18 09:43:40','2026-10-29 07:54:40',NULL,NULL,NULL,NULL,NULL,0,'Cigar lounge in the Se7en Oceans gastronomic complex (Michelin-starred restaurant). Walk-in humidor. Views over the Binnenalster. La Aurora, Davidoff and Cubans. Full cocktail bar.','Cigar lounge en el complejo gastronómico Se7en Oceans (restaurante con estrella Michelin). Humidor walk-in. Vistas al Binnenalster. La Aurora, Davidoff y cubanos. Bar de cócteles completo.','Zigarrenlounge im Gastronomiekomplex Se7en Oceans (Restaurant mit Michelin-Stern). Begehbarer Humidor. Blick auf die Binnenalster. La Aurora, Davidoff und Kubaner. Vollwertige Cocktailbar.','雪茄休息室，位于美食综合体 Se7en Oceans（米其林星级餐厅）内。设步入式雪茄柜。可眺望 Binnenalster。La Aurora、Davidoff 与古巴雪茄。配备完整的鸡尾酒吧。','صالة سيجار داخل المجمّع الغاستروني Se7en Oceans (مطعم حائز على نجوم ميشلان). مستودع ترطيب يمكن دخوله. إطلالة على بحيرة Binnenalster. La Aurora وDavidoff وسيجار كوبي. بار كوكتيل متكامل.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (38,'germany','Atlantic Hotel Bar & Smoker\'s Lounge','Hamburg — An der Alster 72-79, 20099','Hôtel 5 étoiles Cigar Lounge','+49 40 28880','€€€€','Grand hôtel légendaire de Hambourg face au lac Alster. Lounge Davidoff attenant au bar Atlantic. Décor vert, fauteuils cuir, ambiance détendue. Ouvert dim-jeu 10h-minuit, ven-sam 10h-1h.','londoncigarsmoker.com vérifiée sur place',1,'2026-03-18 09:43:40','2026-10-21 17:16:22',NULL,NULL,NULL,NULL,NULL,0,'Legendary grand hotel in Hamburg facing Lake Alster. Davidoff lounge adjoining the Atlantic bar. Green decor, leather armchairs, relaxed atmosphere. Open Sun–Thu 10am–midnight, Fri–Sat 10am–1am.','Gran hotel legendario de Hamburgo frente al lago Alster. Lounge Davidoff contiguo al bar Atlantic. Decoración verde, sillones de cuero, ambiente relajado. Abierto de dom. a jue. de 10:00 a 24:00 y vie.-sáb. de 10:00 a 1:00.','Legendäres Grandhotel in Hamburg an der Alster. Davidoff-Lounge neben der Atlantic-Bar. Grünes Dekor, Ledersessel, entspannte Atmosphäre. Geöffnet So–Do 10–24 Uhr, Fr–Sa 10–1 Uhr.','汉堡传奇大酒店，面朝阿尔斯特湖。Davidoff 雪茄厅紧邻 Atlantic 酒吧。绿色装潢、皮质扶手椅，氛围轻松。周日至周四 10:00–24:00，周五至周六 10:00–1:00。','فندق فخم أسطوري في هامبورغ يطلّ على بحيرة ألستر. صالة دافيدوف الملاصقة لبار أتلانتيك. ديكور أخضر وكراسي جلدية وأجواء مريحة. يفتح الأحد–الخميس 10:00–24:00، والجمعة–السبت 10:00–1:00.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (39,'germany','La Casa del Habano — Frankfurt','Frankfurt — Kleine Hochstraße 9, 60313','La Casa del Habano Officielle','+49 69 20977955','€€€€','La Casa del Habano officielle de Francfort.','PDF officiel Habanos S.A. — annuaire habanos.com lu le 17 septembre 2026 : une entrée du réseau dans cette ville ; plan des franchises lacasadelhabano.com (état du 30 août 2026, lu le 18 septembre 2026) : une Casa dans cette ville',1,'2026-03-18 09:43:40','2026-09-18 07:58:32',NULL,NULL,NULL,NULL,NULL,0,'Official La Casa del Habano in Frankfurt.','La Casa del Habano oficial de Fráncfort.','Offizielle La Casa del Habano in Frankfurt.','法兰克福官方 La Casa del Habano。','«لا كاسا ديل هابانو» الرسمي في فرانكفورت.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (40,'germany','La Casa del Habano — Berlin (Hotel Savoy)','Berlin — Fasanenstrasse 9-10, Hotel Savoy, 10623','La Casa del Habano Officielle','+49 30 3110 36 46','€€€€','La Casa del Habano de Berlin, dans l\'hôtel Savoy de la Fasanenstrasse.','PDF officiel Habanos S.A. — annuaire habanos.com lu le 17 septembre 2026 : une entrée du réseau dans cette ville ; plan des franchises lacasadelhabano.com (état du 30 août 2026, lu le 18 septembre 2026) : une Casa dans cette ville',1,'2026-03-18 09:43:40','2026-10-21 17:16:22',NULL,NULL,NULL,NULL,NULL,0,'Berlin\'s La Casa del Habano, in the Hotel Savoy on Fasanenstrasse.','La Casa del Habano de Berlín, en el Hotel Savoy de la Fasanenstrasse.','Die La Casa del Habano in Berlin, im Hotel Savoy in der Fasanenstraße.','柏林的 La Casa del Habano，位于 Fasanenstrasse 的 Savoy 酒店内。','«لا كاسا ديل هابانو» في برلين، بفندق سافوي في شارع فازانن.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (41,'germany','La Casa del Habano — Bonn','Bonn','La Casa del Habano Officielle (16e en Allemagne)',NULL,'€€€','Inaugurée en 2025, la 16e La Casa del Habano d\'Allemagne.','habanos.com officiel 2025 — annuaire habanos.com lu le 17 septembre 2026 : une entrée du réseau dans cette ville',1,'2026-03-18 09:43:40','2026-10-21 17:19:55',NULL,NULL,NULL,NULL,NULL,0,'Opened in 2025, Germany\'s 16th La Casa del Habano.','Inaugurada en 2025, la 16.ª La Casa del Habano de Alemania.','2025 eröffnet, die 16. La Casa del Habano Deutschlands.','2025 年开业，德国第 16 家 La Casa del Habano。','افتُتح عام 2025، وهو الفرع السادس عشر لـ«لا كاسا ديل هابانو» في ألمانيا.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (42,'switzerland','La Casa del Habano — Zürich (Bleicherweg)','Zürich — Bleicherweg 18, 8002','La Casa del Habano Officielle (1re de Suisse)','+41 44 202 12 11','€€€€','Première LCDH de Suisse. Propriétaire Samuel Menzi, Habano Man of the Year 2004.','PDF officiel Habanos S.A. — annuaire habanos.com lu le 17 septembre 2026 : une entrée du réseau dans cette ville ; plan des franchises lacasadelhabano.com (état du 30 août 2026, lu le 18 septembre 2026) : une Casa dans cette ville',1,'2026-03-18 09:43:40','2026-10-29 07:39:07',NULL,NULL,NULL,NULL,NULL,0,'Switzerland\'s first La Casa del Habano. Owner Samuel Menzi, Habano Man of the Year 2004.','La primera La Casa del Habano de Suiza. Propietario: Samuel Menzi, Habano Man of the Year 2004.','Die erste La Casa del Habano der Schweiz. Inhaber Samuel Menzi, Habano Man of the Year 2004.','瑞士首家 La Casa del Habano。业主 Samuel Menzi，Habano Man of the Year 2004。','أول «لا كاسا ديل هابانو» في سويسرا. المالك صامويل منزي، حائز لقب Habano Man of the Year لعام 2004.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (43,'switzerland','La Casa del Habano — Basel','Basel — Aeschenvorstadt 48, 4051','La Casa del Habano Officielle','+41 61 272 57 75','€€€€','La Casa del Habano officielle de Bâle. Distributeur Intertabak AG.','PDF officiel Habanos S.A. — annuaire habanos.com lu le 17 septembre 2026 : une entrée du réseau dans cette ville ; plan des franchises lacasadelhabano.com (état du 30 août 2026, lu le 18 septembre 2026) : une Casa dans cette ville',1,'2026-03-18 09:43:40','2026-09-18 07:58:32',NULL,NULL,NULL,NULL,NULL,0,'Official La Casa del Habano in Basel. Distributor Intertabak AG.','La Casa del Habano oficial de Basilea. Distribuidor Intertabak AG.','Offizielle La Casa del Habano in Basel. Vertrieb Intertabak AG.','巴塞尔官方 La Casa del Habano。经销商 Intertabak AG。','«لا كاسا ديل هابانو» الرسمي في بازل. الموزّع Intertabak AG.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (44,'switzerland','La Casa del Habano — Lugano','Lugano — Via Motta 12, 6900','La Casa del Habano Officielle','+41 91 922 57 43','€€€€','La Casa del Habano officielle de Lugano (Suisse italienne).','PDF officiel Habanos S.A. — annuaire habanos.com lu le 17 septembre 2026 : une entrée du réseau dans cette ville ; plan des franchises lacasadelhabano.com (état du 30 août 2026, lu le 18 septembre 2026) : une Casa dans cette ville',1,'2026-03-18 09:43:40','2026-09-18 07:58:32',NULL,NULL,NULL,NULL,NULL,0,'Official La Casa del Habano in Lugano (Italian-speaking Switzerland).','La Casa del Habano oficial de Lugano (Suiza italiana).','Offizielle La Casa del Habano in Lugano (italienischsprachige Schweiz).','卢加诺官方 La Casa del Habano（瑞士意大利语区）。','«لا كاسا ديل هابانو» الرسمي في لوغانو (سويسرا الناطقة بالإيطالية).',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (45,'switzerland','La Casa del Habano — Nyon','Nyon, bords du Lac Léman','La Casa del Habano Officielle (seule en Suisse Romande)',NULL,'€€€€','Seule LCDH de Suisse romande. Raretés et éditions exclusives non disponibles ailleurs. Distributeur Intertabak AG.','habanos.com officiel — annuaire habanos.com lu le 17 septembre 2026 : une entrée du réseau dans cette ville ; plan des franchises lacasadelhabano.com (état du 30 août 2026, lu le 18 septembre 2026) : une Casa dans cette ville',1,'2026-03-18 09:43:40','2026-09-18 07:58:32',NULL,NULL,NULL,NULL,NULL,0,'The only La Casa del Habano in French-speaking Switzerland. Rarities and exclusive editions unavailable elsewhere. Distributed by Intertabak AG.','La única La Casa del Habano de la Suiza francófona. Rarezas y ediciones exclusivas no disponibles en otros lugares. Distribuida por Intertabak AG.','Die einzige La Casa del Habano der Westschweiz. Raritäten und exklusive Editionen, die es sonst nirgends gibt. Vertrieb durch Intertabak AG.','瑞士法语区唯一的 La Casa del Habano。备有别处买不到的珍品与专属版本。由 Intertabak AG 供货。','«لا كاسا ديل هابانو» الوحيد في سويسرا الناطقة بالفرنسية. نوادر وإصدارات حصرية لا تتوفّر في مكان آخر. يورّده Intertabak AG.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (46,'switzerland','La Casa del Habano — Mendrisio','Mendrisio — Via Angelo Maspoli 11 (près FoxTown)','La Casa del Habano Officielle',NULL,'€€€','9e LCDH de Suisse, inaugurée avril 2024. Propriétaires Alain Proietto & Sofia Belfasto.','habanos.com officiel 2024 — annuaire habanos.com lu le 17 septembre 2026 : une entrée du réseau dans cette ville',1,'2026-03-18 09:43:40','2026-09-17 23:14:27',NULL,NULL,NULL,NULL,NULL,0,'Switzerland\'s 9th La Casa del Habano, opened in April 2024. Owners Alain Proietto & Sofia Belfasto.','La 9.ª La Casa del Habano de Suiza, inaugurada en abril de 2024. Propietarios: Alain Proietto y Sofia Belfasto.','Die 9. La Casa del Habano der Schweiz, eröffnet im April 2024. Inhaber: Alain Proietto & Sofia Belfasto.','瑞士第 9 家 La Casa del Habano，2024 年 4 月开业。业主为 Alain Proietto 与 Sofia Belfasto。','تاسع «لا كاسا ديل هابانو» في سويسرا، افتُتح في أبريل 2024. المالكان ألان بروييتو وصوفيا بلفاستو.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (47,'uk','James J. Fox — St James\'s Street (fondé 1787)','London — 19 St James\'s Street, SW1A 1ES','Cigare Merchant Historique (fondé 1787)','+44 20 7930 3787','€€€€','Maison fondée en 1787 par Robert Lewis, réunie à James J. Fox en 1992. Salon de dégustation de 27 places au premier étage, musée Churchill au sous-sol. Clients historiques : Winston Churchill — sa dernière commande date du 23 décembre 1964 — et Oscar Wilde. L\'un des rares lieux du Royaume-Uni où l\'on peut fumer à l\'intérieur, au titre de l\'exemption accordée aux buralistes spécialisés.','jjfox.co.uk officiel',1,'2026-03-18 09:43:40','2026-10-29 12:49:17',NULL,NULL,NULL,NULL,NULL,0,'Founded in 1787 by Robert Lewis and merged with James J. Fox in 1992. A 27-seat tasting lounge on the first floor, a Churchill museum in the basement. Historic customers: Winston Churchill — his last order dated 23 December 1964 — and Oscar Wilde. One of the few places in the UK where you may smoke indoors, under the exemption granted to specialist tobacconists.','Casa fundada en 1787 por Robert Lewis y unida a James J. Fox en 1992. Salón de degustación de 27 plazas en la primera planta y museo Churchill en el sótano. Clientes históricos: Winston Churchill —su último pedido data del 23 de diciembre de 1964— y Oscar Wilde. Uno de los pocos lugares del Reino Unido donde se puede fumar en interior, al amparo de la exención concedida a las tabaquerías especializadas.','1787 von Robert Lewis gegründet, 1992 mit James J. Fox zusammengeführt. Verkostungslounge mit 27 Plätzen im ersten Stock, Churchill-Museum im Untergeschoss. Historische Kunden: Winston Churchill — seine letzte Bestellung datiert vom 23. Dezember 1964 — und Oscar Wilde. Einer der wenigen Orte im Vereinigten Königreich, an denen drinnen geraucht werden darf, dank der Ausnahme für Fachhändler.','1787 年由 Robert Lewis 创立，1992 年与 James J. Fox 合并。二楼设 27 座品鉴厅，地下层设丘吉尔博物馆。历史客户包括温斯顿·丘吉尔——他最后一笔订单为 1964 年 12 月 23 日——与奥斯卡·王尔德。依照给予专业烟草商的豁免，这里是英国少数可在室内吸烟的场所之一。','أسّسها روبرت لويس عام 1787 واندمجت مع «جيمس ج. فوكس» عام 1992. صالة تذوّق بسبعة وعشرين مقعدًا في الطابق الأول، ومتحف تشرشل في الطابق السفلي. من زبائنها التاريخيين ونستون تشرشل — وآخر طلبية له بتاريخ 23 ديسمبر 1964 — وأوسكار وايلد. وبفضل الاستثناء الممنوح لتجار التبغ المتخصّصين، هي من الأماكن القليلة في المملكة المتحدة التي يُسمح فيها بالتدخين داخل المبنى.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (48,'uk','James J. Fox — Harrods (La Casa del Habano)','London — Harrods, 87-135 Brompton Road, Knightsbridge, SW1X 7XL','La Casa del Habano dans Harrods',NULL,'€€€€','La Casa del Habano intégrée dans Harrods. Lounge de dégustation 10 places, système Airkel air filtration.','jjfox.co.uk officiel',1,'2026-03-18 09:43:40','2026-10-21 17:19:55',NULL,NULL,NULL,NULL,NULL,0,'La Casa del Habano inside Harrods. A ten-seat tasting lounge with an Airkel air-filtration system.','La Casa del Habano integrada en Harrods. Lounge de degustación de diez plazas con sistema de filtración de aire Airkel.','La Casa del Habano im Inneren von Harrods. Verkostungslounge mit zehn Plätzen und Airkel-Luftfilteranlage.','La Casa del Habano 设于 Harrods 内。10 座品鉴休息室，配备 Airkel 空气过滤系统。','«لا كاسا ديل هابانو» داخل متجر هارودز. صالة تذوّق بعشرة مقاعد، ونظام Airkel لتنقية الهواء.',NULL,NULL,NULL);
