INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (113,'saudiarabia','La Casa del Habano — Jeddah (Palestine Street)','Jeddah — Palestine Street, Al Hamra','La Casa del Habano Officielle','+966 12 667 2752','€€€€','Casa del Habano de Djeddah, Palestine Street, dans le quartier d\'Al Hamra. Le plan des franchises de La Casa del Habano la compte ; l\'annuaire habanos.com classe la même adresse sous le nom La Casa Cubana, Habanos Specialist — les deux sont écrits.','PDF officiel Habanos S.A. ; plan des franchises lacasadelhabano.com (état du 30 août 2026, lu le 18 septembre 2026) : une Casa à Djeddah ; l\'annuaire habanos.com (4 437 lieux, lu le 17 septembre 2026) classe la même adresse La Casa Cubana, Habanos Specialist — les deux écrits ; téléphone pris à l\'annuaire',1,'2026-03-18 09:43:40','2026-10-29 07:54:40',NULL,NULL,NULL,NULL,NULL,0,'Casa del Habano of Jeddah, Palestine Street, in the Al Hamra district. The La Casa del Habano franchise map counts it; the habanos.com directory lists the same address under the name La Casa Cubana, Habanos Specialist — both are written.','Casa del Habano de Yeda, Palestine Street, en el barrio de Al Hamra. El mapa de franquicias de La Casa del Habano la cuenta; el directorio de habanos.com registra la misma dirección con el nombre La Casa Cubana, Habanos Specialist — se escriben las dos.','Casa del Habano von Dschidda, Palestine Street, im Viertel Al Hamra. Die Franchise-Karte von La Casa del Habano zählt sie; das Verzeichnis von habanos.com führt dieselbe Adresse unter dem Namen La Casa Cubana, Habanos Specialist — beides ist vermerkt.','吉达的 Casa del Habano，位于哈姆拉区巴勒斯坦街。La Casa del Habano 的特许经营地图将其计入；habanos.com 的名录则以 La Casa Cubana（Habanos Specialist）之名列出同一地址——两者都写在这里。','Casa del Habano في جدّة، شارع فلسطين بحيّ الحمراء. تعدّها خريطة امتيازات La Casa del Habano؛ ويدرج دليل habanos.com العنوان نفسه باسم La Casa Cubana بوصفه Habanos Specialist — والاثنان مكتوبان.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (114,'saudiarabia','La Casa del Habano — Riyadh (Olaya)','Riyadh — Prince Sultan Bin Abdulaziz, St. Olaya','La Casa del Habano Officielle','+966 1465 4737','€€€€','La Casa del Habano officielle de Riyadh dans le quartier Olaya.','PDF officiel Habanos S.A. ; plan des franchises lacasadelhabano.com (état du 30 août 2026, lu le 18 septembre 2026) : deux Casas à Riyad ; l\'annuaire habanos.com (4 437 lieux, lu le 17 septembre 2026) n\'y classe que La Casa Cubana, Habanos Specialist — les deux écrits ; l\'adresse de la fiche n\'est confirmée par aucun des deux',1,'2026-03-18 09:43:40','2026-09-18 07:58:32',NULL,NULL,NULL,NULL,NULL,0,'Official La Casa del Habano in Riyadh\'s Olaya district.','La Casa del Habano oficial de Riad, en el barrio de Olaya.','Offizielle La Casa del Habano in Riad, im Viertel Olaya.','利雅得官方 La Casa del Habano，位于奥拉亚区。','«لا كاسا ديل هابانو» الرسمي في الرياض، بحي العليا.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (115,'saudiarabia','La Casa del Habano — Al Khobar','Al Khobar — 28th Street','La Casa del Habano Officielle','+966 3 8874255','€€€','La Casa del Habano officielle d\'Al Khobar, sur la 28e rue.','PDF officiel Habanos S.A. ; plan des franchises lacasadelhabano.com (état du 30 août 2026, lu le 18 septembre 2026) : une Casa à Khobar ; l\'annuaire habanos.com (4 437 lieux, lu le 17 septembre 2026) n\'y classe que La Casa Cubana, Habanos Specialist, 4733 Prince Faisal Bin Fahd Road — les deux écrits ; l\'adresse de la fiche n\'est confirmée par aucun des deux',1,'2026-03-18 09:43:40','2026-09-18 07:58:32',NULL,NULL,NULL,NULL,NULL,0,'Official La Casa del Habano in Al Khobar, on 28th Street.','La Casa del Habano oficial en Al Khobar, en la calle 28.','Offizielle La Casa del Habano in Al Khobar, in der 28th Street.','胡拜尔官方 La Casa del Habano，位于第 28 街。','«لا كاسا ديل هابانو» الرسمي في الخبر، بالشارع الثامن والعشرين.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (116,'japan','La Casa del Habano by Cigar Club Iikura','Tokyo — 2-3-9 Azabudai, Minato-ku','La Casa del Habano Officielle','+81 3 3583 7130','€€€€','La Casa del Habano officielle de Tokyo. Yutaka Kobayashi, Master Trainer Habanos Academia.','PDF officiel Habanos S.A., cigarjournal.com — annuaire habanos.com lu le 17 septembre 2026 : une entrée du réseau dans cette ville ; plan des franchises lacasadelhabano.com (état du 30 août 2026, lu le 18 septembre 2026) : une Casa dans cette ville',1,'2026-03-18 09:43:40','2026-10-21 17:19:55',NULL,NULL,NULL,NULL,NULL,0,'Tokyo\'s official La Casa del Habano. Yutaka Kobayashi, Master Trainer of the Habanos Academia.','La Casa del Habano oficial de Tokio. Yutaka Kobayashi, Master Trainer de la Habanos Academia.','Die offizielle La Casa del Habano von Tokio. Yutaka Kobayashi, Master Trainer der Habanos Academia.','东京的官方 La Casa del Habano。Yutaka Kobayashi，Habanos Academia 认证 Master Trainer。','«لا كاسا ديل هابانو» الرسمية في طوكيو. يوتاكا كوباياشي، مدرّب رئيسي (Master Trainer) لدى أكاديمية هابانوس.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (117,'japan','Davidoff of Geneva — Ginza Flagship','Tokyo — 8-5-6 Ginza, Chuo-ku','Davidoff Flagship','+81 3 5537 6511','€€€€','Flagship Davidoff de Tokyo à Ginza. Refuge pour executives depuis le ban sur le tabac dans les bureaux. Davidoff Signature 2000 et Aniversario Special R populaires.','cigarjournal.com',1,'2026-03-18 09:43:40','2026-10-29 12:49:18',NULL,NULL,NULL,NULL,NULL,0,'Davidoff\'s Tokyo flagship in Ginza. A refuge for executives since smoking was banned in offices. The Davidoff Signature 2000 and the Aniversario Special R are popular.','Tienda insignia de Davidoff en Tokio, en Ginza. Refugio de ejecutivos desde la prohibición de fumar en las oficinas. El Davidoff Signature 2000 y el Aniversario Special R son muy populares.','Davidoffs Tokioter Flagshipstore in Ginza. Zufluchtsort für Führungskräfte, seit in Büros nicht mehr geraucht werden darf. Beliebt sind die Davidoff Signature 2000 und die Aniversario Special R.','位于银座的东京 Davidoff 旗舰店。自办公场所禁烟以来，成为高管们的避风港。Davidoff Signature 2000 与 Aniversario Special R 广受欢迎。','متجر دافيدوف الرئيسي في طوكيو بحي غينزا. ملاذ للمديرين منذ حظر التدخين في المكاتب. دافيدوف سيغنتشر 2000 وأنيفرسايو سبيشال R رائجان.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (118,'japan','Le Connaisseur — Roppongi','Tokyo — 1-14-1 Nishiazabu, Minato-ku (Roppongi)','Cigar Bar (Cohiba Atmosphere)','+81 3 3796 3696','€€€€','Répertorié par Habanos S.A. comme Cohiba Atmosphere. Lounge cigares de référence à Tokyo. Hisashi Shimura derrière le bar depuis 20 ans. Ouvert jusqu\'à 4h le week-end.','cigarjournal.com, PDF officiel Habanos S.A. — annuaire habanos.com lu le 17 septembre 2026 : une entrée du réseau dans cette ville',1,'2026-03-18 09:43:40','2026-10-21 17:16:22',NULL,NULL,NULL,NULL,NULL,0,'Listed by Habanos S.A. as a Cohiba Atmosphere. Tokyo\'s benchmark cigar lounge. Hisashi Shimura has been behind the bar for twenty years. Open until 4am at weekends.','Registrado por Habanos S.A. como Cohiba Atmosphere. El cigar lounge de referencia de Tokio. Hisashi Shimura lleva veinte años tras la barra. Abierto hasta las 4:00 los fines de semana.','Von Habanos S.A. als Cohiba Atmosphere gelistet. Tokios maßgebliche Zigarrenlounge. Hisashi Shimura steht seit zwanzig Jahren hinter der Bar. Am Wochenende bis 4 Uhr geöffnet.','Habanos S.A. 将其列为 Cohiba Atmosphere。东京的标杆雪茄厅。Hisashi Shimura 已在吧台后驻守二十年。周末营业至凌晨 4 点。','مُدرج لدى هابانوس ش.م. بصفته «كوهيبا أتموسفير». صالة السيجار المرجعية في طوكيو. هيساشي شيمورا خلف البار منذ عشرين عامًا. يفتح حتى الرابعة فجرًا في عطلة نهاية الأسبوع.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (119,'japan','Tableaux Lounge — Daikanyama','Tokyo — Daikanyama, Shibuya-ku','Cigar Bar & Live Jazz','+81 3 5489 2201','€€€€','Salon international à Daikanyama. Jazz live de musiciens de passage, vaste cave humidifiée, cocktails soignés. Lustres, parquet poli, fauteuils de cuir.','cigarjournal.com, flavoredtimes.com',1,'2026-03-18 09:43:40','2026-08-26 11:06:16',NULL,NULL,NULL,NULL,NULL,0,'An international lounge in Daikanyama. Live jazz from visiting musicians, an extensive humidified cellar, carefully made cocktails. Chandeliers, polished parquet, leather armchairs.','Salón internacional en Daikanyama. Jazz en directo con músicos de paso, amplia bodega humidificada y cócteles cuidados. Lámparas de araña, parqué pulido y sillones de cuero.','Eine internationale Lounge in Daikanyama. Live-Jazz durchreisender Musiker, ein großer Humidorraum und sorgfältig gemixte Cocktails. Kronleuchter, poliertes Parkett, Ledersessel.','位于代官山的国际风格休息室。有客座乐手的现场爵士乐、宽敞的恒湿雪茄库与精心调制的鸡尾酒。水晶吊灯、抛光木地板与皮质扶手椅。','صالة ذات طابع دولي في دايكانياما. جاز حيّ بعزف موسيقيين زائرين، ومخزن ترطيب واسع، وكوكتيلات متقنة. ثريّات، وأرضية باركيه مصقولة، وأرائك جلدية.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (120,'japan','R261 Cigar & Rock (Cerulean Tower Tokyu Hotel)','Tokyo — Cerulean Tower, 26-1 Sakuragaokacho, Shibuya','Hotel Cigar Bar','+81 3 3476 3000','€€€€','Bar cigares rock au Cerulean Tower Hotel. 270 cigares de 45 variétés (Cuba, Rep. Dom.). Davidoff, Cohiba, Montecristo, Partagas. Whiskys japonais single malt, cognacs. Ouvert 16h-minuit.','tokyuhotels.co.jp officiel',1,'2026-03-18 09:43:40','2026-10-29 12:49:18',NULL,NULL,NULL,NULL,NULL,0,'A rock-themed cigar bar in the Cerulean Tower Hotel. Two hundred and seventy cigars across forty-five varieties, from Cuba and the Dominican Republic: Davidoff, Cohiba, Montecristo, Partagás. Japanese single malts and cognacs. Open from 4pm to midnight.','Bar de puros de ambiente rock en el Cerulean Tower Hotel. Doscientos setenta puros de cuarenta y cinco variedades, de Cuba y la República Dominicana: Davidoff, Cohiba, Montecristo, Partagás. Whiskies japoneses single malt y coñacs. Abierto de 16:00 a medianoche.','Zigarrenbar im Rock-Stil im Cerulean Tower Hotel. Zweihundertsiebzig Zigarren in fünfundvierzig Sorten, aus Kuba und der Dominikanischen Republik: Davidoff, Cohiba, Montecristo, Partagás. Japanische Single Malts und Cognacs. Geöffnet von 16 Uhr bis Mitternacht.','位于 Cerulean Tower Hotel 内的摇滚主题雪茄吧。备有来自古巴与多米尼加的四十五个品种、共二百七十支雪茄：Davidoff、Cohiba、Montecristo、Partagás。另供应日本单一麦芽威士忌与干邑。营业时间 16:00 至午夜。','بار سيجار بطابع الروك داخل فندق سيروليان تاور. مئتان وسبعون سيجارًا من خمسة وأربعين صنفًا، من كوبا وجمهورية الدومينيكان: دافيدوف، كوهيبا، مونتيكريستو، بارتاغاس. ويسكي ياباني سينغل مولت وكونياك. يفتح من الرابعة عصرًا حتى منتصف الليل.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (121,'japan','Ritz-Carlton Tokyo — Lobby Lounge','Tokyo — Midtown 9-7-1, Akasaka, Minato-ku (45e étage)','Hotel Cigar Lounge','+81 3 6434 8711','€€€€','Salon cigares au 45e étage de la tour Tokyo Midtown. Vue panoramique sur la ville, cave humidifiée soignée.','flavoredtimes.com',1,'2026-03-18 09:43:40','2026-10-21 17:16:22',NULL,NULL,NULL,NULL,NULL,0,'Cigar lounge on the 45th floor of the Tokyo Midtown tower. Panoramic views over the city and a well-kept humidified cellar.','Salón de puros en la planta 45 de la torre Tokyo Midtown. Vistas panorámicas de la ciudad y bodega humidificada cuidada.','Zigarrenlounge im 45. Stock des Tokyo-Midtown-Turms. Panoramablick über die Stadt und ein sorgfältig gepflegter Humidorraum.','位于 Tokyo Midtown 大厦 45 层的雪茄休息室。可全景俯瞰城市，恒湿雪茄库打理得当。','صالة سيجار في الطابق الخامس والأربعين من برج «طوكيو ميدتاون». إطلالة بانورامية على المدينة، ومخزن ترطيب مُعتنى به.',NULL,NULL,NULL);
