INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (158,'argentina','Cohiba Atmosphere — Buenos Aires','Buenos Aires — Moreno 518, San Telmo, C1091AAL','Cohiba Atmosphere Officielle','+54 11 4342 4300','€€€€','Salon Cohiba Atmosphere du quartier colonial de San Telmo, à Buenos Aires. Service complet autour des Habanos, dans le réseau officiel de salons de la marque.','habanos.com — fiche officielle Cohiba Atmosphere Buenos Aires — annuaire habanos.com lu le 17 septembre 2026 : une entrée du réseau dans cette ville',1,'2026-03-18 09:43:40','2026-10-21 17:16:22',NULL,NULL,NULL,NULL,NULL,0,'Cohiba Atmosphere lounge in the colonial district of San Telmo, Buenos Aires. Full service built around Habanos, within the brand\'s official network of lounges.','Salón Cohiba Atmosphere en el barrio colonial de San Telmo, en Buenos Aires. Servicio completo en torno a los Habanos, dentro de la red oficial de salones de la marca.','Cohiba-Atmosphere-Lounge im Kolonialviertel San Telmo in Buenos Aires. Vollständiger Service rund um Habanos, innerhalb des offiziellen Lounge-Netzes der Marke.','位于布宜诺斯艾利斯圣特尔莫殖民老城区的 Cohiba Atmosphere 雪茄吧，属于该品牌的官方雪茄吧网络，围绕 Habanos 提供全套服务。','صالة كوهيبا أتموسفير في حي سان تيلمو الاستعماري ببوينس آيرس. خدمة متكاملة حول سيجار هابانوس، ضمن الشبكة الرسمية لصالات العلامة.',NULL,NULL,NULL);
