INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (246,'spain','La Casa del Habano — Madrid (Castellana)','Madrid — Paseo de la Castellana 36','La Casa del Habano Officielle','+34 91 435 35 25','€€€€','La plus vaste Casa del Habano de Madrid, sur le Paseo de la Castellana. Cave humidifiée monumentale où l\'on entre, bar à whisky, et l\'un des choix Habanos les plus larges de la capitale.','RETIRÉ — cette adresse ne figure dans aucune source du réseau espagnol',0,'2026-03-18 23:04:48','2026-09-05 02:13:42',NULL,NULL,NULL,NULL,NULL,0,'The largest Casa del Habano in Madrid, on the Paseo de la Castellana. A monumental walk-in humidor, a whisky bar, and one of the widest Habanos selections in the capital.','La Casa del Habano más amplia de Madrid, en el Paseo de la Castellana. Humidor monumental por el que se entra, bar de whisky y una de las selecciones de Habanos más completas de la capital.','Die größte Casa del Habano Madrids, am Paseo de la Castellana. Ein begehbarer Monumental-Humidor, eine Whiskybar und eine der breitesten Habanos-Auswahlen der Hauptstadt.','马德里最大的 Casa del Habano，位于卡斯特利亚纳大道。可步入的巨型恒湿库、威士忌吧，以及首都最齐全的哈瓦那雪茄选择之一。','أكبر «كازا ديل هابانو» في مدريد، على جادة كاستيانا. مخزن ترطيب ضخم يُدخل إليه، وبار ويسكي، وواحدة من أوسع تشكيلات الهابانوس في العاصمة.',NULL,NULL,NULL);
