INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (256,'spain','La Casa del Habano — Bilbao','Bilbao — Gran Vía 29','La Casa del Habano Officielle','+34 94 423 55 78','€€€','La Casa del Habano du Pays basque, dans la Gran Vía de Bilbao.','RETIRÉ — cette adresse ne figure dans aucune source du réseau espagnol',0,'2026-03-18 23:04:48','2026-09-05 02:13:42',NULL,NULL,NULL,NULL,NULL,0,'The Basque Country\'s La Casa del Habano, on Bilbao\'s Gran Vía.','La Casa del Habano del País Vasco, en la Gran Vía de Bilbao.','Die La Casa del Habano des Baskenlands, an der Gran Vía in Bilbao.','巴斯克地区的 La Casa del Habano，位于毕尔巴鄂 Gran Vía 大道。','«لا كاسا ديل هابانو» في إقليم الباسك، بشارع غران فيا في بلباو.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (257,'spain','El Gran Fumador — San Sebastián','San Sebastián — Calle San Marcial 18','Cave Premium','+34 943 42 89 12','€€€','L\'adresse cigare de référence de Saint-Sébastien, capitale mondiale de la gastronomie. Événements réguliers d\'accords Habanos-gastronomie, sélection cubaine exceptionnelle.','RETIRÉ — relu le 17 septembre 2026 : aucune trace au 18 calle San Marcial, à deux lecteurs ; la cave citée de Donostia est l\'Estanco 31 de Agosto',0,'2026-03-18 23:04:48','2026-09-18 07:10:28',NULL,NULL,NULL,NULL,NULL,0,'San Sebastián\'s reference cigar address in the gastronomic world capital. Regular Habanos-gastronomy pairing events, exceptional Cuban selection.','La dirección cigarrera de referencia de San Sebastián, capital mundial de la gastronomía. Eventos periódicos de maridaje Habanos-gastronomía y selección cubana excepcional.','Die maßgebliche Zigarrenadresse in San Sebastián, der Welthauptstadt der Gastronomie. Regelmäßige Habanos-Gastronomie-Pairings, außergewöhnliche kubanische Auswahl.','圣塞瓦斯蒂安的标杆雪茄之所——世界美食之都。定期举办哈瓦那雪茄与美食搭配活动，古巴选品出众。','عنوان السيجار المرجعي في سان سيباستيان، عاصمة فنّ الطهو العالمية. فعاليات دورية لمزاوجة هابانوس مع الطعام، وتشكيلة كوبية استثنائية.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (276,'uk','Davidoff of London — St James\'s Street','London — 35 St James\'s Street, SW1A 1HD','Davidoff Appointed Merchant','+44 20 7930 3079','€€€€','Davidoff of London, 35 St James\'s Street, dans la rue des marchands de cigares de St James\'s : la boutique d\'Edward Sahakian, qui porte le nom de la marque et en tient toute la gamme. Le localisateur Davidoff la classe parmi ses dépositaires agréés, non parmi ses boutiques en propre.','le localisateur davidoff.com (56 boutiques en propre, 14 partenaires, 1 636 dépositaires, lu le 18 septembre 2026) : Davidoff of London, 35 St James\'s Street, classée dépositaire agréé (Davidoff Appointed Merchant), non boutique en propre ; davidofflondon.com, qui se présente comme la boutique de cigares d\'Edward Sahakian',1,'2026-03-18 23:04:48','2026-09-18 07:58:32',NULL,NULL,'https://www.davidofflondon.com/',NULL,NULL,0,'Davidoff of London, 35 St James\'s Street, in the cigar merchants\' street of St James\'s: Edward Sahakian\'s shop, which bears the brand\'s name and carries its whole range. The Davidoff locator classes it among its appointed merchants, not among its own stores.','Davidoff of London, 35 St James\'s Street, en la calle de los comerciantes de puros de St James\'s: la tienda de Edward Sahakian, que lleva el nombre de la marca y ofrece toda su gama. El localizador Davidoff la clasifica entre sus distribuidores autorizados, no entre sus tiendas propias.','Davidoff of London, 35 St James\'s Street, in der Straße der Zigarrenhändler von St James\'s: das Geschäft von Edward Sahakian, das den Namen der Marke trägt und ihr ganzes Sortiment führt. Der Davidoff-Locator stuft es unter seine autorisierten Händler ein, nicht unter seine eigenen Geschäfte.','伦敦圣詹姆斯街35号的 Davidoff of London，位于圣詹姆斯的雪茄商街：爱德华·萨哈基安的店铺，冠以品牌之名并经营其全系列产品。Davidoff 的门店定位器将其归入授权经销商，而非自营门店。','Davidoff of London، 35 شارع سانت جيمس، في شارع تجّار السيجار بسانت جيمس: متجر إدوارد ساهاكيان، الذي يحمل اسم العلامة ويقدّم تشكيلتها كاملة. يصنّفه محدّد متاجر Davidoff ضمن وكلائها المعتمدين لا ضمن متاجرها الخاصّة.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (277,'uk','Sautter of Mayfair','London — 106 Mount Street, Mayfair, W1K 2TW','Cave Premium','+44 20 7499 4866','€€€€','Maison de Mount Street fondée il y a plus de cinquante ans, installée à cette adresse depuis plus de trente. Havanes vieillis et millésimes anciens. Une seconde adresse à Knightsbridge, 8 Raphael Street.','sauttercigars.com',1,'2026-03-18 23:04:48','2026-09-04 17:20:49',NULL,NULL,'https://www.sauttercigars.com/',NULL,NULL,0,'Mount Street house founded over fifty years ago, at this address for more than thirty. Aged Havanas and old vintages. A second address in Knightsbridge, 8 Raphael Street.','Casa de Mount Street fundada hace más de cincuenta años, en esta dirección desde hace más de treinta. Habanos envejecidos y añadas antiguas. Una segunda dirección en Knightsbridge, 8 Raphael Street.','Haus in der Mount Street, vor über fünfzig Jahren gegründet, seit mehr als dreißig Jahren an dieser Adresse. Gereifte Havannas und alte Jahrgänge. Eine zweite Adresse in Knightsbridge, 8 Raphael Street.','芒特街的老字号，创立逾五十年，在此地址经营超过三十年。以陈年哈瓦那雪茄与旧年份存货见长。另于骑士桥 8 Raphael Street 设有第二家门店。','دار في شارع ماونت تأسست قبل أكثر من خمسين عامًا، وفي هذا العنوان منذ أكثر من ثلاثين. سيجار هافانا معتّق وسنوات إنتاج قديمة. ولها عنوان ثانٍ في نايتسبريدج، 8 Raphael Street.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (278,'uk','The Ritz — Cigar Terrace','London — 150 Piccadilly, Mayfair, W1J 9BR','Palace Cigar Lounge','+44 20 7493 8181','€€€€','La terrasse cigare privée du Ritz London, au 150 Piccadilly. Accessible aux membres et aux clients de l\'hôtel ; cocktails signature, et une adresse qui sert la royauté depuis plus d\'un siècle.','theritzlondon.com',1,'2026-03-18 23:04:48','2026-10-29 07:39:05',NULL,NULL,NULL,NULL,NULL,0,'The Ritz London\'s private cigar terrace at 150 Piccadilly. Accessible to members and hotel guests; signature cocktails and an address that has served royalty for over a century.','La terraza de puros privada del Ritz London, en el 150 de Piccadilly. Accesible a socios y huéspedes del hotel; cócteles de autor y una dirección que sirve a la realeza desde hace más de un siglo.','Die private Zigarrenterrasse des Ritz London, 150 Piccadilly. Zugänglich für Mitglieder und Hotelgäste; Signature-Cocktails und eine Adresse, die seit über einem Jahrhundert Könige bedient.','Ritz London 的私人雪茄露台，位于 150 Piccadilly。仅限会员与酒店住客；招牌鸡尾酒，且这个地址服务王室已逾一个世纪。','شرفة السيجار الخاصة في فندق The Ritz London، 150 Piccadilly. متاحة للأعضاء ونزلاء الفندق؛ كوكتيلات مميّزة، وعنوان يخدم الأسرة المالكة منذ ما يزيد على قرن.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (279,'uk','Claridge\'s — Cigar Room','London — Brook Street, Mayfair, W1K 4HR','Palace Cigar Room','+44 20 7629 8860','€€€€','Salon fumeur discret du palace Art Déco Claridge\'s — accès résidents et membres.','claridges.co.uk',1,'2026-03-18 23:04:48','2026-08-01 18:19:56',NULL,NULL,NULL,NULL,NULL,0,'Discreet smoking room at the Art Deco palace hotel Claridge\'s — for residents and members.','Salón de fumadores discreto del palacio art déco Claridge\'s: acceso para residentes y socios.','Diskreter Rauchsalon im Art-déco-Grandhotel Claridge\'s — für Hausgäste und Mitglieder.','装饰艺术风格宫殿酒店 Claridge\'s 内低调的吸烟室——供住客与会员使用。','صالة تدخين هادئة في فندق كلاريدجز بطراز آرت ديكو — للنزلاء والأعضاء.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (280,'uk','The Churchill Bar — Hyatt Regency','London — 30 Portman Square, W1H 7BH','Hotel Cigar Bar Historique','+44 20 7486 5800','€€€€','Le bar éponyme de Churchill — sélection cubains, collection de cognacs anciens, atmosphère victorienne.','hyatt.com',1,'2026-03-18 23:04:48','2026-08-05 12:51:13',NULL,NULL,NULL,NULL,NULL,0,'Churchill\'s eponymous bar — Cuban selection, a collection of old cognacs, Victorian atmosphere.','El bar homónimo de Churchill: selección cubana, colección de coñacs antiguos y ambiente victoriano.','Die nach Churchill benannte Bar — kubanische Auswahl, Sammlung alter Cognacs, viktorianisches Ambiente.','以丘吉尔命名的酒吧——古巴雪茄精选、陈年干邑收藏，维多利亚风格氛围。','البار الذي يحمل اسم تشرشل — تشكيلة كوبية، ومجموعة من الكونياك المعتّق، وأجواء فيكتورية.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (281,'uk','Turmeaus — Liverpool','Liverpool — The Albany Building, 8 Old Hall Street, L3 9PA','Cave & Lounge','+44 151 236 3802','€€€','Turmeaus Cigars & Whisky, boutique de C.Gars Ltd à Liverpool, dans l\'Albany Building, au 8 Old Hall Street : cave où l\'on entre et salon de dégustation. Dans le même bâtiment, le bar Puffin Rooms sert whiskies et cocktails.','turmeaus.co.uk, page Turmeaus Liverpool (adresse, téléphone, cave, salon de dégustation ; avant l\'Albany, Water Street puis Fenwick Street ; lue le 24 septembre 2026) ; puffinrooms.co.uk (bar, même adresse) ; lcdhcigars.uk : les Casas de C.Gars Ltd sont à Chester, Knutsford et Édimbourg ; habanos.com, place Alfie Turmeaus – Liverpool, Habanos Specialist, à l\'ancienne adresse (lu le 17 septembre 2026) — la fiche disait Casa del Habano, 11 Castle Street : aucune source lue ne le porte',1,'2026-03-18 23:04:48','2026-09-25 08:50:40',NULL,NULL,NULL,NULL,NULL,0,'Turmeaus Cigars & Whisky, C.Gars Ltd\'s shop in Liverpool, in the Albany Building at 8 Old Hall Street: walk-in humidor and sampling lounge. In the same building, the Puffin Rooms bar serves whiskies and cocktails.','Turmeaus Cigars & Whisky, tienda de C.Gars Ltd en Liverpool, en el Albany Building, en el 8 de Old Hall Street: humidor visitable y salón de degustación. En el mismo edificio, el bar Puffin Rooms sirve whiskies y cócteles.','Turmeaus Cigars & Whisky, das Geschäft von C.Gars Ltd in Liverpool, im Albany Building, 8 Old Hall Street: begehbarer Humidor und Verkostungslounge. Im selben Gebäude schenkt die Bar Puffin Rooms Whiskys und Cocktails aus.','Turmeaus Cigars & Whisky 是 C.Gars Ltd 在利物浦的门店，位于 Old Hall Street 8号的 Albany Building 内：设有步入式雪茄保湿室和品鉴室。同一栋楼里的 Puffin Rooms 酒吧供应威士忌和鸡尾酒。','Turmeaus Cigars & Whisky، متجر شركة C.Gars Ltd في ليفربول، داخل مبنى Albany Building في 8 Old Hall Street: غرفة ترطيب للسيجار يمكن دخولها وصالة للتذوّق. وفي المبنى نفسه يقدّم بار Puffin Rooms الويسكي والكوكتيلات.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (282,'uk','Turmeaus — Edinburgh','Edinburgh — Unit 2, 11 Lister Square, EH3 9GL','La Casa del Habano Officielle','+44 131 285 8082','€€€','La Casa del Habano de C.Gars Ltd à Édimbourg, au 11 Lister Square, dans l\'ensemble Quartermile : cave où l\'on entre et terrasse chauffée où l\'on fume. Le bar Puffin Rooms, attenant, sert whiskies et cocktails.','lcdhcigars.uk (Unit 2, 11 Lister Square, EH3 9GL ; lu le 24 septembre 2026) ; lacasadelhabano.com, communiqué du 26 septembre 2023 (ouverte le 12 septembre 2023 par C.Gars Ltd) ; cigars.co.uk, localisateur Hunters & Frankau (La Casa del Habano, téléphone) ; turmeaus.co.uk et puffinrooms.co.uk (cave où l\'on entre, terrasse chauffée, bar Puffin Rooms) — absente de l\'annuaire habanos.com (lu le 17 septembre 2026) ; la fiche disait 35 Frederick Street : aucune source lue ne le porte',1,'2026-03-18 23:04:48','2026-09-25 08:50:40',NULL,NULL,NULL,NULL,NULL,0,'C.Gars Ltd\'s La Casa del Habano in Edinburgh, at 11 Lister Square in the Quartermile development: walk-in humidor and heated smoking terrace. The adjoining Puffin Rooms bar serves whiskies and cocktails.','La Casa del Habano de C.Gars Ltd en Edimburgo, en el 11 de Lister Square, dentro del conjunto Quartermile: humidor visitable y terraza calefactada para fumar. El bar Puffin Rooms, contiguo, sirve whiskies y cócteles.','Die La Casa del Habano von C.Gars Ltd in Edinburgh, 11 Lister Square im Quartermile-Areal: begehbarer Humidor und beheizte Raucherterrasse. Die angrenzende Bar Puffin Rooms schenkt Whiskys und Cocktails aus.','C.Gars Ltd 旗下的 La Casa del Habano，位于爱丁堡 Quartermile 街区的 Lister Square 11号：设有步入式雪茄保湿室和带取暖设施的吸烟露台。毗邻的 Puffin Rooms 酒吧供应威士忌和鸡尾酒。','La Casa del Habano التابعة لشركة C.Gars Ltd في إدنبرة، في 11 Lister Square ضمن مجمّع Quartermile: غرفة ترطيب للسيجار يمكن دخولها وتراس مُدفّأ للتدخين. ويقدّم بار Puffin Rooms المجاور الويسكي والكوكتيلات.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (283,'uk','Turmeaus — London (Soho)','London — 37 Old Compton Street, Soho, W1D 6HB','Cave Premium Selfridges','+44 20 7734 0444','€€€','Adresse cigare premium à Londres, 37 Old Compton Street. Sélection de Habanos et de cigares premium.','cgars.co.uk',1,'2026-03-18 23:04:48','2026-08-05 12:51:47',NULL,NULL,NULL,NULL,NULL,0,'Premium cigar address in London — 37 Old Compton Street. Curated selection of Habanos and premium cigars.','Dirección cigarrera premium en Londres, 37 Old Compton Street. Selección de Habanos y puros premium.','Premium-Zigarrenadresse in London, 37 Old Compton Street. Ausgewählte Habanos und Premium-Zigarren.','伦敦老康普顿街 37 号的高端雪茄之所。精选哈瓦那与高端雪茄。','عنوان سيجار فاخر في لندن، 37 أولد كومبتون ستريت. تشكيلة منتقاة من هابانوس والسيجار الفاخر.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (284,'uk','Mitchell\'s of Glasgow','Glasgow — 11 Hanover Street, G1 2DL','Cave Premium','+44 141 221 3341','€€€','Fondée en 1875, cave historique de Glasgow spécialisée en cubains.','RETIRÉ — aucune trace de cet établissement, et le domaine cité n\'existe pas',0,'2026-03-18 23:04:48','2026-09-04 17:20:49',NULL,NULL,NULL,NULL,NULL,0,'Founded in 1875, a historic Glasgow cigar shop specialising in Cubans.','Fundado en 1875, estanco histórico de Glasgow especializado en cubanos.','1875 gegründet, ein historischer Glasgower Zigarrenladen mit Schwerpunkt auf Kubanern.','创立于 1875 年的格拉斯哥老牌雪茄行，专营古巴雪茄。','تأسّس عام 1875، متجر سيجار عريق في غلاسكو متخصّص في السيجار الكوبي.',NULL,NULL,NULL);
