INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (330,'italy','La Casa del Habano — Napoli (Sisimbro)','Napoli — Via San Pasquale a Chiaia 74, 80121','La Casa del Habano Officielle','+39 081 406983','€€€','Troisième Casa del Habano d\'Italie, après Milan et Rome. La tabaccheria Sisimbro, ouverte en 1959 entre la piazza Amedeo et la piazza San Pasquale, a rejoint le réseau en 2019. Cave et salon pour fumer sur place.','habanos.com — fiche officielle La Casa del Habano Napoli — annuaire habanos.com lu le 17 septembre 2026 : une entrée du réseau dans cette ville ; plan des franchises lacasadelhabano.com (état du 30 août 2026, lu le 18 septembre 2026) : une Casa dans cette ville',1,'2026-03-18 23:04:48','2026-09-18 07:58:32',NULL,NULL,NULL,NULL,NULL,0,'Third Casa del Habano in Italy, after Milan and Rome. The Sisimbro tabaccheria, opened in 1959 between Piazza Amedeo and Piazza San Pasquale, joined the network in 2019. Humidor and a lounge for smoking on site.','Tercera Casa del Habano de Italia, tras Milán y Roma. La tabaccheria Sisimbro, abierta en 1959 entre la piazza Amedeo y la piazza San Pasquale, entró en la red en 2019. Humidor y salón para fumar in situ.','Dritte Casa del Habano Italiens, nach Mailand und Rom. Die Tabaccheria Sisimbro, 1959 zwischen Piazza Amedeo und Piazza San Pasquale eröffnet, kam 2019 ins Netz. Humidor und Lounge zum Rauchen vor Ort.','意大利第三家 La Casa del Habano，继米兰与罗马之后。Sisimbro 烟草行于 1959 年开设于阿梅代奥广场与圣帕斯夸莱广场之间，2019 年加入该网络。设雪茄柜与可现场吸烟的休息厅。','ثالث «كاسا ديل هابانو» في إيطاليا، بعد ميلانو وروما. افتُتح متجر التبغ سيسيمبرو عام 1959 بين ساحة أميديو وساحة سان باسكوالي، وانضمّ إلى الشبكة عام 2019. مستودع ترطيب وصالة للتدخين في المكان.',NULL,NULL,NULL);
