INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (365,'japan','Davidoff of Geneva since 1911 — Ginza','Tokyo — Ginza 8-5-6, Chuo-ku','Davidoff Flagship','+81 3 5537 5585','€€€€','Boutique Davidoff of Geneva since 1911 de Ginza, 8-5-6 Ginza, dans l\'arrondissement de Chuo à Tokyo, avec salon ; le localisateur de la marque la liste parmi ses boutiques en propre. La fiche la plaçait au Ginza Six, 6-10-1, une adresse que le localisateur ne connaît pas.','le localisateur davidoff.com (56 boutiques en propre, 14 partenaires, 1 636 dépositaires, lu le 18 septembre 2026) : boutique en propre Davidoff of Geneva since 1911 – Ginza, Chuo City, Ginza 8 Chome-5-6, avec salon, davidoffgeneva.jp — la fiche la plaçait au Ginza Six, 6-10-1, que le localisateur ne connaît pas',1,'2026-03-18 23:04:48','2026-09-18 07:58:32',NULL,NULL,'https://davidoffgeneva.jp/',NULL,NULL,0,'Davidoff of Geneva since 1911 shop in Ginza, 8-5-6 Ginza, in Tokyo\'s Chuo ward, with a lounge; the brand\'s locator lists it among its own stores. The entry placed it at Ginza Six, 6-10-1, an address the locator does not know.','Tienda Davidoff of Geneva since 1911 de Ginza, 8-5-6 Ginza, en el distrito de Chuo en Tokio, con salón; el localizador de la marca la registra entre sus tiendas propias. La ficha la situaba en Ginza Six, 6-10-1, una dirección que el localizador no conoce.','Davidoff-of-Geneva-since-1911-Boutique in Ginza, 8-5-6 Ginza, im Tokioter Bezirk Chuo, mit Lounge; der Store-Locator der Marke führt sie unter ihren eigenen Geschäften. Der Eintrag setzte sie ins Ginza Six, 6-10-1, eine Adresse, die der Locator nicht kennt.','东京中央区银座8-5-6的 Davidoff of Geneva since 1911 精品店，设有休息厅；品牌的门店定位器将其列入自营门店。此前词条把它放在银座六丁目6-10-1的 Ginza Six，定位器并不知道这一地址。','متجر Davidoff of Geneva since 1911 في غينزا، 8-5-6 غينزا بحيّ تشوو في طوكيو، مع صالة؛ يدرجه محدّد المتاجر الخاصّ بالعلامة ضمن متاجرها الخاصّة. كانت البطاقة تضعه في Ginza Six، 6-10-1، وهو عنوان لا يعرفه المحدّد.',NULL,NULL,NULL);
