INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (384,'hongkong','La Casa del Habano — Kowloon','Hong Kong — Sheraton Hong Kong Hotel & Towers, 20 Nathan Road, Kowloon','La Casa del Habano Officielle',NULL,'€€€€','La Casa del Habano de Kowloon, au Sheraton de Nathan Road. Approvisionnée par Pacific Cigar, distributeur d\'Habanos pour l\'Asie-Pacifique.','habanomag.com, d\'après habanos.com — annuaire habanos.com lu le 17 septembre 2026 : une entrée du réseau dans cette ville ; plan des franchises lacasadelhabano.com (état du 30 août 2026, lu le 18 septembre 2026) : une Casa dans cette ville',1,'2026-03-18 23:04:48','2026-10-21 17:16:22',NULL,NULL,NULL,NULL,NULL,0,'La Casa del Habano in Kowloon, at the Sheraton on Nathan Road. Supplied by Pacific Cigar, the Habanos distributor for Asia-Pacific.','La Casa del Habano de Kowloon, en el Sheraton de Nathan Road. Abastecida por Pacific Cigar, distribuidor de Habanos para Asia-Pacífico.','La Casa del Habano in Kowloon, im Sheraton an der Nathan Road. Beliefert von Pacific Cigar, dem Habanos-Distributor für Asien-Pazifik.','位于九龙弥敦道 Sheraton 酒店的 La Casa del Habano。由亚太区 Habanos 经销商 Pacific Cigar 供货。','«لا كاسا ديل هابانو» في كولون، داخل فندق شيراتون بشارع ناثان. يزوّدها Pacific Cigar، موزّع هابانوس لآسيا والمحيط الهادئ.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (385,'hongkong','Bertie HK','Hong Kong — Duke Wellington House, 14-24 Wellington Street, 4/F, Central','Habanos Specialist','+852 2619 9418','€€€€','Salon de cigares de Central, au quatrième étage de Duke Wellington House, à l\'entrée de Lan Kwai Fong. Humidor climatisé avec casiers de membres, salon principal, salon privé et terrasse couverte.','bertie-hk.com',1,'2026-03-18 23:04:48','2026-10-21 17:16:22','Lun–Sam 12h–0h · Dim 14h–22h',NULL,'https://www.bertie-hk.com/',NULL,NULL,0,'Cigar lounge in Central, on the fourth floor of Duke Wellington House, at the entrance to Lan Kwai Fong. Climate-controlled walk-in humidor with member lockers, main lounge, private room and covered terrace.','Salón de puros en Central, en la cuarta planta de Duke Wellington House, a la entrada de Lan Kwai Fong. Humidor climatizado con casilleros para socios, salón principal, sala privada y terraza cubierta.','Zigarrenlounge in Central, im vierten Stock des Duke Wellington House, am Eingang von Lan Kwai Fong. Klimatisierter begehbarer Humidor mit Mitgliederfächern, Hauptlounge, Separee und überdachte Terrasse.','位于中环 Duke Wellington House 四楼的雪茄吧，紧邻兰桂坊入口。设有恒温恒湿步入式雪茄柜与会员储柜、主厅、私人包厢及有盖露台。','صالة سيجار في حي سنترال، في الطابق الرابع من مبنى ديوك ولينغتون، عند مدخل لان كواي فونغ. مستودع ترطيب مكيّف مع خزائن للأعضاء، وصالة رئيسية، وغرفة خاصة، وشرفة مسقوفة.',NULL,NULL,NULL);
