INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (410,'usa','Davidoff of Geneva — Miami','Miami, FL — 9700 Collins Ave, Bal Harbour Shops','Davidoff Flagship','+1 305 868 5600','€€€€','Flagship Davidoff dans les Bal Harbour Shops — sélection complète, humidor privé sur rendez-vous.','RETIRÉ — relu le 18 septembre 2026 : absente de le localisateur davidoff.com (56 boutiques en propre, 14 partenaires, 1 636 dépositaires, lu le 18 septembre 2026) : ses boutiques en propre de Floride sont à Hollywood (Hard Rock) ; à Miami, six dépositaires, aucun à Bal Harbour',0,'2026-03-18 23:04:48','2026-09-18 07:58:32',NULL,NULL,NULL,NULL,NULL,0,'Davidoff flagship in the Bal Harbour Shops — complete selection, private humidor by appointment.','Tienda insignia de Davidoff en las Bal Harbour Shops: selección completa y humidor privado con cita previa.','Davidoff-Flagshipstore in den Bal Harbour Shops — komplette Auswahl, privater Humidor nach Vereinbarung.','位于 Bal Harbour Shops 的大卫杜夫旗舰店——完整精选，私人雪茄柜需预约。','متجر دافيدوف الرئيسي في «بال هاربر شوبس» — تشكيلة كاملة ومرطّبة خاصة بموعد مسبق.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (411,'usa','Casa de Montecristo — Miami','Miami, FL — 1535 NW 79th Ave, Doral','Cave & Lounge','+1 786 401 4042','€€€','Le concept store amiral de General Cigar, à Miami. La plus grande cave humidifiée accessible du sud de la Floride, fauteuils de salon haut de gamme, et l\'ensemble du portefeuille des grandes marques.','montecristo.com',1,'2026-03-18 23:04:48','2026-10-21 17:19:55',NULL,NULL,NULL,NULL,NULL,0,'General Cigar\'s flagship concept store in Miami. The largest walk-in humidor in South Florida, premium lounge seating, and the full portfolio of the major brands.','La tienda insignia de General Cigar en Miami. El mayor humidor accesible del sur de Florida, butacas de salón de alta gama y toda la cartera de las grandes marcas.','Der Flagship-Concept-Store von General Cigar in Miami. Der größte begehbare Humidor Südfloridas, hochwertige Loungesessel und das gesamte Portfolio der großen Marken.','General Cigar 在迈阿密的旗舰概念店。设有南佛罗里达规模庞大的步入式恒湿雪茄柜、高级休息区座席，并陈列各大品牌的完整产品线。','متجر General Cigar الرئيسي من نوع «كونسبت ستور» في ميامي. مستودع ترطيب ضخم يمكن دخوله في جنوب فلوريدا، ومقاعد صالة فاخرة، وكامل مجموعة العلامات الكبيرة.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (412,'usa','Tobacco Road Cigars — Fort Lauderdale','Fort Lauderdale, FL — 230 SW 2nd St','Cave & Lounge','+1 954 522 1833','€€€','Cave historique du centre-ville, humidor bien fourni, espace fumeur confortable.','RETIRÉ — relu le 17 septembre 2026 : aucune trace au 230 SW 2nd St ni sous ce nom à Fort Lauderdale ; le Tobacco Road de Floride était un bar de Miami, fermé et démoli en 2014',0,'2026-03-18 23:04:48','2026-09-18 07:10:28',NULL,NULL,NULL,NULL,NULL,0,'Historic downtown cigar shop, a well-stocked humidor and a comfortable smoking area.','Cava histórico du centre-ville, humidor bien fourni, espace fumeur confortable.','Keller historisch du centre-ville, Humidor bien fourni, espace fumeur confortable.','历史悠久的雪茄酒窖 du centre-ville, 雪茄保湿箱 bien fourni, espace fumeur confortable.','كهف سيجار تاريخي du centre-ville, الهيوميدور bien fourni, espace fumeur confortable.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (413,'usa','Havana Connections — Tampa','Tampa, FL — 16006 N Dale Mabry Hwy','Cave Premium','+1 813 961 1912','€€€','Adresse répertoriée sur North Dale Mabry Highway, à Tampa (Floride). La fiche la donnait pour une Casa del Habano : le réseau n\'a aucune adresse aux États-Unis, où les cigares cubains ne sont pas vendus.','RETIRÉ — relu le 17 septembre 2026 : havanaconnections.com, Virginia\'s Humidor, n\'a d\'adresses qu\'en Virginie ; rien à Tampa',0,'2026-03-18 23:04:48','2026-09-18 07:10:28',NULL,NULL,NULL,NULL,NULL,0,'An address listed on North Dale Mabry Highway in Tampa, Florida. The entry called it a Casa del Habano: the network has no address in the United States, where Cuban cigars are not sold.','Dirección registrada en North Dale Mabry Highway, en Tampa (Florida). La ficha la daba por una Casa del Habano: la red no tiene ninguna dirección en Estados Unidos, donde no se venden puros cubanos.','Eine verzeichnete Adresse am North Dale Mabry Highway in Tampa, Florida. Der Eintrag führte sie als Casa del Habano: Das Netz hat keine Adresse in den Vereinigten Staaten, wo kubanische Zigarren nicht verkauft werden.','美国佛罗里达州坦帕市北戴尔马布里公路上的一处登记地址。原条目称其为 Casa del Habano：该网络在美国没有任何门店，古巴雪茄在美国不得销售。','عنوان مسجَّل في طريق نورث ديل مابري السريع بمدينة تامبا في ولاية فلوريدا. كانت البطاقة تعدّه من «كازا ديل هابانو»: وليس للشبكة أي عنوان في الولايات المتحدة، حيث لا تُباع السيجار الكوبي.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (414,'usa','Casa de Montecristo — Orlando','Orlando, FL — 7339 W Sand Lake Rd','Cave & Lounge','+1 407 203 1414','€€€','Grande cave à cigares sur le Restaurant Row d\'Orlando, West Sand Lake Road.','montecristo.com',1,'2026-03-18 23:04:48','2026-09-03 12:11:42',NULL,NULL,NULL,NULL,NULL,0,'Large cigar shop on Orlando\'s Restaurant Row, West Sand Lake Road.','Gran estanco en el Restaurant Row de Orlando, West Sand Lake Road.','Großer Zigarrenladen an Orlandos Restaurant Row, West Sand Lake Road.','位于奥兰多 Restaurant Row（西沙湖路）的大型雪茄行。','متجر سيجار كبير في «ريستورانت رو» بأورلاندو، طريق ويست ساند ليك.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (415,'usa','Davidoff of Geneva since 1911 — Las Vegas','Las Vegas, NV — 3200 S Las Vegas Blvd, suite 1245','Davidoff Flagship','+1 702 473 5001','€€€€','Boutique Davidoff of Geneva since 1911 de Las Vegas, 3200 South Las Vegas Boulevard, suite 1245, avec salon et bar à cigares ; le localisateur de la marque la liste parmi ses boutiques en propre. La fiche la plaçait au Palazzo, 3325 Las Vegas Boulevard, une adresse que le localisateur ne connaît pas.','le localisateur davidoff.com (56 boutiques en propre, 14 partenaires, 1 636 dépositaires, lu le 18 septembre 2026) : boutique en propre Davidoff of Geneva since 1911 – Las Vegas, 3200 S Las Vegas Blvd #1245, avec salon, davidoffcigarbarlv.com — la fiche la plaçait au Palazzo, 3325 Las Vegas Blvd, que le localisateur ne connaît pas',1,'2026-03-18 23:04:48','2026-09-18 07:58:32',NULL,NULL,'http://www.davidoffcigarbarlv.com/',NULL,NULL,0,'Davidoff of Geneva since 1911 shop in Las Vegas, 3200 South Las Vegas Boulevard, suite 1245, with a lounge and cigar bar; the brand\'s locator lists it among its own stores. The entry placed it at the Palazzo, 3325 Las Vegas Boulevard, an address the locator does not know.','Tienda Davidoff of Geneva since 1911 de Las Vegas, 3200 South Las Vegas Boulevard, local 1245, con salón y bar de puros; el localizador de la marca la registra entre sus tiendas propias. La ficha la situaba en el Palazzo, 3325 Las Vegas Boulevard, una dirección que el localizador no conoce.','Davidoff-of-Geneva-since-1911-Boutique in Las Vegas, 3200 South Las Vegas Boulevard, Suite 1245, mit Lounge und Zigarrenbar; der Store-Locator der Marke führt sie unter ihren eigenen Geschäften. Der Eintrag setzte sie ins Palazzo, 3325 Las Vegas Boulevard, eine Adresse, die der Locator nicht kennt.','拉斯维加斯南拉斯维加斯大道3200号1245室的 Davidoff of Geneva since 1911 精品店，设有休息厅和雪茄吧；品牌的门店定位器将其列入自营门店。此前词条把它放在拉斯维加斯大道3325号的 Palazzo，定位器并不知道这一地址。','متجر Davidoff of Geneva since 1911 في لاس فيغاس، 3200 جادة لاس فيغاس الجنوبية، جناح 1245، مع صالة وبار سيجار؛ يدرجه محدّد المتاجر الخاصّ بالعلامة ضمن متاجرها الخاصّة. كانت البطاقة تضعه في البالاتسو، 3325 جادة لاس فيغاس، وهو عنوان لا يعرفه المحدّد.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (416,'usa','Casa Fuente — Forum Shops Caesars','Las Vegas, NV — 3500 Las Vegas Blvd S, Forum Shops','Flagship Lounge & Cave','+1 702 731 5051','€€€€','La seule boutique de détail de la famille Arturo Fuente hors de République dominicaine. Tenue par la famille ; la seule adresse où l\'approvisionnement en Opus X est garanti.','arturo-fuente.com',1,'2026-03-18 23:04:48','2026-10-21 17:16:22',NULL,NULL,NULL,NULL,NULL,0,'The Arturo Fuente family\'s only retail boutique outside the Dominican Republic. Run by the family; the only address where Opus X stock is guaranteed.','La única boutique minorista de la familia Arturo Fuente fuera de la República Dominicana. Gestionada por la familia; la única dirección donde el stock de Opus X está garantizado.','Die einzige Einzelhandelsboutique der Familie Arturo Fuente außerhalb der Dominikanischen Republik. Von der Familie geführt; die einzige Adresse mit garantiertem Opus-X-Bestand.','Arturo Fuente 家族在多米尼加共和国之外唯一的零售店。由家族亲自经营，也是唯一保证有 Opus X 现货的地方。','المتجر الوحيد لعائلة أرتورو فوينتي خارج جمهورية الدومينيكان. تديره العائلة، وهو العنوان الوحيد الذي يضمن توفّر أوبوس X.',NULL,NULL,NULL);
