INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (421,'usa','Davidoff of Geneva — Beverly Hills','Beverly Hills, CA — 256 N Rodeo Drive','Davidoff Flagship','+1 310 385 0555','€€€€','Le vaisseau amiral de Davidoff sur Rodeo Drive, à Beverly Hills. Service attentif, collection Davidoff complète, casiers privés pour les clients réguliers.','RETIRÉ — relu le 18 septembre 2026 : absente de le localisateur davidoff.com (56 boutiques en propre, 14 partenaires, 1 636 dépositaires, lu le 18 septembre 2026) : aucune boutique ni dépositaire à Beverly Hills',0,'2026-03-18 23:04:48','2026-09-18 07:58:32',NULL,NULL,NULL,NULL,NULL,0,'Davidoff\'s Rodeo Drive flagship in Beverly Hills. White-glove service, the complete Davidoff collection, and private humidor storage for regular clients.','La tienda insignia de Davidoff en Rodeo Drive, en Beverly Hills. Servicio esmerado, colección Davidoff completa y casilleros privados para los clientes habituales.','Davidoffs Flagshipstore am Rodeo Drive in Beverly Hills. Aufmerksamer Service, die vollständige Davidoff-Kollektion und private Humidorfächer für Stammkunden.','大卫杜夫在比佛利山罗迪欧大道的旗舰店。服务周到，陈列大卫杜夫完整系列，并为常客提供私人储柜。','متجر دافيدوف الرئيسي في شارع روديو درايف ببيفرلي هيلز. خدمة دقيقة، وتشكيلة دافيدوف الكاملة، وخزائن ترطيب خاصة للزبائن الدائمين.',NULL,NULL,NULL);
