INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (423,'usa','Havana Social — Dallas','Dallas, TX — 3699 McKinney Ave','Cigar Bar & Whisky Lounge','+1 214 443 9945','€€€','Lounge cigares haut de gamme dans le quartier d\'Uptown à Dallas. Cocktails d\'auteur, sélection de cigares premium, soirées régulières d\'accords whisky-cigare.','RETIRÉ — nom d\'une maison réelle, à une adresse qui n\'est pas la sienne',0,'2026-03-18 23:04:48','2026-09-04 17:37:41',NULL,NULL,NULL,NULL,NULL,0,'Upscale cigar lounge in Dallas\'s Uptown neighborhood. Craft cocktails, premium cigar selection, regular whisky-and-cigar pairing events.','Cigar lounge de gama alta en el barrio de Uptown de Dallas. Cócteles de autor, selección de puros premium y veladas periódicas de maridaje whisky-puro.','Gehobene Zigarrenlounge im Dallas-Viertel Uptown. Craft-Cocktails, Premium-Zigarrenauswahl, regelmäßige Whisky-Zigarren-Pairing-Abende.','达拉斯上城区的高档雪茄厅。手作鸡尾酒、高端雪茄精选，定期举办威士忌与雪茄搭配之夜。','صالة سيجار راقية في حي أب تاون بدالاس. كوكتيلات حرفية وتشكيلة سيجار فاخرة وأمسيات دورية لمزاوجة الويسكي بالسيجار.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (424,'usa','L.J. Peretti Co.','Boston, MA — 2½ Park Square','Civette Historique (fondée 1870)','+1 617 482 0218','€€€','Le plus ancien buraliste de Boston, fondé en 1870. Assemblages sur mesure, millésimes rares, et une clientèle qui traverse plusieurs générations depuis Harvard Square.','ljperetti.com',1,'2026-03-18 23:04:48','2026-10-21 17:19:55',NULL,NULL,NULL,NULL,NULL,0,'Boston\'s oldest tobacconist, founded in 1870. Custom blends, rare vintages, and a clientele spanning several generations from Harvard Square.','El estanco más antiguo de Boston, fundado en 1870. Mezclas a medida, añadas raras y una clientela de varias generaciones desde Harvard Square.','Bostons ältester Tabakhändler, gegründet 1870. Maßgeschneiderte Blends, seltene Jahrgänge und eine Kundschaft über mehrere Generationen vom Harvard Square.','创立于 1870 年的波士顿老牌烟草店。提供定制调配与稀有年份雪茄，客源来自 Harvard Square 一带，已传承数代。','متجر تبغ عريق في بوسطن، تأسّس عام 1870. خلطات حسب الطلب، وسنوات إنتاج نادرة، وزبائن من أجيال متعاقبة في هارفارد سكوير.',NULL,NULL,NULL);
