INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2545,'benin','La Casa del Habano — Cotonou','Cotonou — Cadjèhoun, Avenue Jean-Paul II','La Casa del Habano Officielle','+229 21 30 18 00','€€€','La Casa del Habano officielle de Cotonou, capitale économique du Bénin et premier marché de l\'art d\'Afrique de l\'Ouest. Portefeuille Habanos complet pour un public du cigare premium en croissance.','RETIRÉ — ce pays n\'a pas de La Casa del Habano ; le réseau y a un autre échelon, ou rien',0,'2026-03-22 18:57:48','2026-09-04 23:07:22',NULL,NULL,NULL,NULL,NULL,0,'Official La Casa del Habano in Cotonou, Benin\'s economic capital and West Africa\'s most important art market. Full Habanos portfolio for the growing premium cigar audience.','La Casa del Habano oficial de Cotonú, capital económica de Benín y principal mercado del arte de África Occidental. Portafolio completo de Habanos para un público del puro premium en crecimiento.','Offizielle La Casa del Habano in Cotonou, der Wirtschaftshauptstadt Benins und wichtigstem Kunstmarkt Westafrikas. Komplettes Habanos-Portfolio für ein wachsendes Premium-Zigarrenpublikum.','科托努官方 La Casa del Habano——贝宁经济首都，西非最重要的艺术市场。完整的哈瓦那雪茄产品线，面向不断成长的高端雪茄客群。','«لا كاسا ديل هابانو» الرسمي في كوتونو، العاصمة الاقتصادية لبنين وأهم سوق للفن في غرب أفريقيا. تشكيلة هابانوس الكاملة لجمهور متنامٍ من محبّي السيجار الفاخر.',NULL,NULL,NULL);
