INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2551,'burkina','La Casa del Habano — Ouagadougou','Ouagadougou — Avenue Kwame Nkrumah, Secteur 4','La Casa del Habano Officielle','+226 25 30 60 00','€€','La Casa del Habano officielle de Ouagadougou, au cœur enclavé de l\'Afrique de l\'Ouest. Portefeuille Habanos complet pour les milieux d\'affaires burkinabè et les professionnels des agences de développement installés dans la capitale.','RETIRÉ — ce pays n\'a pas de La Casa del Habano ; le réseau y a un autre échelon, ou rien',0,'2026-03-22 18:57:48','2026-09-04 23:07:22',NULL,NULL,NULL,NULL,NULL,0,'Official La Casa del Habano in Ouagadougou, the land-locked heart of West Africa. Full Habanos portfolio for the Burkinabe business community and development agency professionals based in the capital.','La Casa del Habano oficial de Uagadugú, en el corazón sin litoral de África Occidental. Portafolio completo de Habanos para la comunidad empresarial burkinesa y los profesionales de las agencias de desarrollo instalados en la capital.','Offizielle La Casa del Habano in Ouagadougou, im binnenländischen Herzen Westafrikas. Komplettes Habanos-Portfolio für die burkinische Geschäftswelt und die in der Hauptstadt ansässigen Fachleute der Entwicklungsagenturen.','瓦加杜古官方 La Casa del Habano——西非内陆腹地。完整的哈瓦那雪茄产品线，服务于布基纳法索商界与常驻首都的发展机构专业人士。','«لا كاسا ديل هابانو» الرسمي في واغادوغو، في القلب الحبيس لغرب أفريقيا. تشكيلة هابانوس الكاملة لأوساط الأعمال البوركينية ولمهنيّي وكالات التنمية المقيمين في العاصمة.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2552,'burkina','Hôtel Laïco — Cigar Bar','Ouagadougou — Hôtel Laïco, Avenue du Président Maurice Yaméogo','Hotel Cigar Bar','+226 25 30 60 60','€€€','Hôtel Laïco, avenue du Président Maurice Yaméogo, à Ouagadougou. Un espace cigares y est annoncé ; aucune source publique ne le décrit.','à vérifier — relu le 17 septembre 2026 : l\'hôtel Laïco existe, son site (laicohotels.com) ne se lit pas depuis un robot, aucune presse consultable ne décrit son bar à cigares',1,'2026-03-22 18:57:48','2026-10-29 07:54:41',NULL,NULL,'https://www.laicohotels.com',NULL,NULL,0,'Hôtel Laïco, Avenue du Président Maurice Yaméogo, Ouagadougou. A cigar space is listed there; no public source describes it.','Hôtel Laïco, avenida del Presidente Maurice Yaméogo, en Uagadugú. Se indica allí un espacio para puros; ninguna fuente pública lo describe.','Hôtel Laïco, Avenue du Président Maurice Yaméogo, Ouagadougou. Ein Zigarrenbereich ist dort angekündigt; keine öffentliche Quelle beschreibt ihn.','Hôtel Laïco，位于瓦加杜古的莫里斯·亚梅奥果总统大道。该处标注设有雪茄区，但没有公开来源对其作出描述。','فندق لايكو في جادة الرئيس موريس ياميوغو بمدينة واغادوغو. يُشار إلى وجود ركن للسيجار في المكان، لكن لا يصفه أي مصدر عام.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2553,'burkina','Splendid Hôtel — VIP Lounge','Ouagadougou — Hôtel Splendid, Avenue de l\'Indépendance','Hotel Cigar Lounge','+226 25 33 21 10','€€','Splendid Hôtel, avenue de l\'Indépendance, dans le centre de Ouagadougou. Un espace cigares y est annoncé ; aucune source publique ne le décrit.','à vérifier — relu le 17 septembre 2026 : l\'hôtel existe — 147 chambres, rouvert après l\'attentat du 15 janvier 2016 —, un guide le place avenue Kwame N\'Krumah, la fiche avenue de l\'Indépendance, les deux sont écrits ; le site que la fiche annonçait ne résout plus ; aucune source ne décrit son VIP lounge',1,'2026-03-22 18:57:48','2026-10-29 07:54:41',NULL,NULL,NULL,NULL,NULL,0,'Splendid Hôtel, Avenue de l\'Indépendance, in central Ouagadougou. A cigar space is listed there; no public source describes it.','Splendid Hôtel, avenida de la Independencia, en el centro de Uagadugú. Se indica allí un espacio para puros; ninguna fuente pública lo describe.','Splendid Hôtel, Avenue de l\'Indépendance, im Zentrum von Ouagadougou. Ein Zigarrenbereich ist dort angekündigt; keine öffentliche Quelle beschreibt ihn.','Splendid Hôtel，位于瓦加杜古市中心独立大道。该处标注设有雪茄区，但没有公开来源对其作出描述。','فندق سبلينديد في جادة الاستقلال بوسط واغادوغو. يُشار إلى وجود ركن للسيجار في المكان، لكن لا يصفه أي مصدر عام.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2554,'mali','Azalaï Hôtel Bamako (ex-Hôtel Salam) — Espace Cigares','Bamako — Azalaï Hôtel Bamako, Avenue de l\'OUA, Badalabougou','Hotel Cigar Space','+223 20 21 17 60','€€€','L\'ancien Hôtel Salam, avenue de l\'OUA à Badalabougou, sur la rive droite du Niger à Bamako, porte aujourd\'hui le nom d\'Azalaï Hôtel Bamako : le groupe Azalaï le présente ainsi, avec son restaurant Nomad, deux bars, une terrasse, une piscine et un spa. Un espace cigares y est annoncé ; aucune source publique ne le décrit.','à vérifier — relu le 17 septembre 2026 : l\'hôtel existe, sous le nom Azalaï Hôtel Bamako (azalai.com : restaurant Nomad, deux bars, terrasse, piscine, spa, sans mot d\'un fumoir), ex-Azalaï Hôtel Salam d\'après les plateformes de réservation ; son salon cigares n\'est décrit nulle part',1,'2026-03-22 18:57:48','2026-10-21 17:16:23',NULL,NULL,'https://www.azalai.com/en/azalai-hotel-bamako',NULL,NULL,0,'The former Hôtel Salam, Avenue de l\'OUA in Badalabougou, on the right bank of the Niger in Bamako, now bears the name Azalaï Hôtel Bamako: the Azalaï group presents it so, with its restaurant Nomad, two bars, a terrace, a pool and a spa. A cigar space is listed there; no public source describes it.','El antiguo Hôtel Salam, avenida de la OUA en Badalabougou, en la orilla derecha del Níger en Bamako, lleva hoy el nombre de Azalaï Hôtel Bamako: así lo presenta el grupo Azalaï, con su restaurante Nomad, dos bares, una terraza, una piscina y un spa. Se anuncia allí un espacio de puros; ninguna fuente pública lo describe.','Das frühere Hôtel Salam, Avenue de l\'OUA in Badalabougou, am rechten Nigerufer in Bamako, trägt heute den Namen Azalaï Hôtel Bamako: so stellt es die Azalaï-Gruppe vor, mit dem Restaurant Nomad, zwei Bars, einer Terrasse, einem Pool und einem Spa. Ein Zigarrenbereich ist dort angekündigt; keine öffentliche Quelle beschreibt ihn.','巴马科尼日尔河右岸巴达拉布古区非统大道上的原 Hôtel Salam，如今名为 Azalaï Hôtel Bamako：Azalaï 集团如此介绍它，设有 Nomad 餐厅、两间酒吧、露台、泳池和水疗中心。该处标注设有雪茄区，但没有公开来源对其作出描述。','فندق سلام السابق، في جادة منظمة الوحدة الأفريقية ببادالابوغو على الضفّة اليمنى لنهر النيجر في باماكو، يحمل اليوم اسم Azalaï Hôtel Bamako: هكذا تقدّمه مجموعة أزالاي، مع مطعمه نوماد وبارين وشرفة ومسبح ومنتجع صحّي. يُعلَن فيه عن ركن للسيجار؛ ولا يصفه أيّ مصدر عامّ.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2555,'mali','Azalaï Grand Hôtel — Fumoir','Bamako — Azalaï Grand Hôtel, Square Lumumba','Hotel Cigar Lounge','+223 20 22 21 22','€€€','Azalaï Grand Hôtel, square Lumumba, dans le centre de Bamako. Un espace cigares y est annoncé ; aucune source publique ne le décrit.','à vérifier — relu le 17 septembre 2026 : l\'hôtel existe (azalai.com : restaurant Gourmet, un bar, une terrasse, une piscine), son salon cigares n\'est décrit nulle part',1,'2026-03-22 18:57:48','2026-10-29 07:54:41',NULL,NULL,'https://www.azalai.com/en/grand-hotel-bamako',NULL,NULL,0,'Azalaï Grand Hôtel, Square Lumumba, in central Bamako. A cigar space is listed there; no public source describes it.','Azalaï Grand Hôtel, plaza Lumumba, en el centro de Bamako. Se indica allí un espacio para puros; ninguna fuente pública lo describe.','Azalaï Grand Hôtel, Square Lumumba, im Zentrum von Bamako. Ein Zigarrenbereich ist dort angekündigt; keine öffentliche Quelle beschreibt ihn.','Azalaï Grand Hôtel，位于巴马科市中心卢蒙巴广场。该处标注设有雪茄区，但没有公开来源对其作出描述。','فندق أزالاي الكبير في ساحة لومومبا بوسط باماكو. يُشار إلى وجود ركن للسيجار في المكان، لكن لا يصفه أي مصدر عام.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2557,'cambodia','Bertie Phnom Penh','Phnom Penh — House 16, Street 13, Village 9, Sangkat Wat Phnom, Khan Daun Penh','Cave & Lounge','+855 10 567 825',NULL,'Salon de cigares du quartier de Wat Phnom, face à la poste centrale. Humidor climatisé, salon principal, salon privé et mezzanine ; carte de vins et spiritueux composée pour les accords.','bertie-pnh.com',1,'2026-09-04 11:33:20','2026-10-21 17:16:23','Lun–Sam 12h–0h · Dim 14h–0h',NULL,'https://www.bertie-pnh.com/',NULL,NULL,0,'Cigar lounge in the Wat Phnom district, opposite the central post office. Climate-controlled walk-in humidor, main lounge, private room and mezzanine; wine and spirits list put together for pairings.','Salón de puros en el barrio de Wat Phnom, frente a la oficina central de correos. Humidor climatizado, salón principal, sala privada y entreplanta; carta de vinos y destilados compuesta para los maridajes.','Zigarrenlounge im Viertel Wat Phnom, gegenüber der Hauptpost. Klimatisierter begehbarer Humidor, Hauptlounge, Separee und Zwischengeschoss; Wein- und Spirituosenkarte für Pairings zusammengestellt.','位于 Wat Phnom 区的雪茄吧，与中央邮局相对。设有恒温恒湿雪茄柜、主厅、私人包厢及夹层；酒单为搭配雪茄而设。','صالة سيجار في حي وات فنوم، مقابل مكتب البريد المركزي. مستودع ترطيب مكيّف، وصالة رئيسية، وغرفة خاصة، وطابق معلّق؛ وقائمة نبيذ ومشروبات روحية أُعدّت للمزاوجة.',NULL,NULL,NULL);
